(function (root) {
"use strict";

/* ---------- deterministic RNG (xorshift32) ---------- */
function RNG(seed){
  let s = (seed >>> 0) || 0x9e3779b9;
  return function(){ s ^= s<<13; s>>>=0; s ^= s>>17; s ^= s<<5; s>>>=0; return s/4294967296; };
}
function pick(R,a){ return a[Math.floor(R()*a.length)]; }
function pickN(R,a,n){ const c=a.slice(); const o=[]; while(o.length<n && c.length) o.push(c.splice(Math.floor(R()*c.length),1)[0]); return o; }
function ri(R,lo,hi,step){ step=step||1; const n=Math.floor((hi-lo)/step)+1; return lo+step*Math.floor(R()*n); }
function rf(R,lo,hi,dec){ const v=lo+R()*(hi-lo); const m=Math.pow(10,dec===undefined?2:dec); return Math.round(v*m)/m; }
function rsign(R){ return R()<0.5?-1:1; }
function shuffle(R,a){ a=a.slice(); for(let i=a.length-1;i>0;i--){ const j=Math.floor(R()*(i+1)); [a[i],a[j]]=[a[j],a[i]]; } return a; }
/* standard normal via Box–Muller, deterministic in R */
function rn(R){ let u=0,v=0; while(u===0)u=R(); while(v===0)v=R();
  return Math.sqrt(-2*Math.log(u))*Math.cos(2*Math.PI*v); }

/* ---------- normal distribution ---------- */
function Phi(x){
  /* Hart's algorithm in West's (2005) form: accurate to about 1e-15, where the
     A&S 7.1.26 series it replaces was good to 1.5e-7 — coarser than the
     tolerance some option-pricing items are marked to. */
  const a=Math.abs(x); let c;
  if(a>37){ c=0; }
  else{
    const e=Math.exp(-a*a/2); let b,d;
    if(a<7.07106781186547){
      b=3.52624965998911e-02*a+0.700383064443688;
      b=b*a+6.37396220353165;  b=b*a+33.912866078383;
      b=b*a+112.079291497871;  b=b*a+221.213596169931;
      b=b*a+220.206867912376;
      d=8.83883476483184e-02*a+1.75566716318264;
      d=d*a+16.064177579207;   d=d*a+86.7807322029461;
      d=d*a+296.564248779674;  d=d*a+637.333633378831;
      d=d*a+793.826512519948;  d=d*a+440.413735824752;
      c=e*b/d;
    } else {
      d=a+0.65; d=a+4/d; d=a+3/d; d=a+2/d; d=a+1/d;
      c=e/(d*2.506628274631);
    }
  }
  return x>0 ? 1-c : c;
}
function erf(x){ return 2*Phi(x*Math.SQRT2)-1; }
function phi(z){ return Math.exp(-z*z/2)/Math.sqrt(2*Math.PI); }
function Phinv(p){
  const a=[-3.969683028665376e+1,2.209460984245205e+2,-2.759285104469687e+2,1.383577518672690e+2,-3.066479806614716e+1,2.506628277459239e+0];
  const b=[-5.447609879822406e+1,1.615858368580409e+2,-1.556989798598866e+2,6.680131188771972e+1,-1.328068155288572e+1];
  const c=[-7.784894002430293e-3,-3.223964580411365e-1,-2.400758277161838e+0,-2.549732539343734e+0,4.374664141464968e+0,2.938163982698783e+0];
  const d=[7.784695709041462e-3,3.224671290700398e-1,2.445134137142996e+0,3.754408661907416e+0];
  const pl=0.02425;
  if(p<pl){const q=Math.sqrt(-2*Math.log(p));return (((((c[0]*q+c[1])*q+c[2])*q+c[3])*q+c[4])*q+c[5])/((((d[0]*q+d[1])*q+d[2])*q+d[3])*q+1);}
  if(p>1-pl){const q=Math.sqrt(-2*Math.log(1-p));return -(((((c[0]*q+c[1])*q+c[2])*q+c[3])*q+c[4])*q+c[5])/((((d[0]*q+d[1])*q+d[2])*q+d[3])*q+1);}
  const q=p-0.5,r=q*q;
  return (((((a[0]*r+a[1])*r+a[2])*r+a[3])*r+a[4])*r+a[5])*q/(((((b[0]*r+b[1])*r+b[2])*r+b[3])*r+b[4])*r+1);
}

/* ---------- Black–Scholes ---------- */
function bsD1(S,K,r,q,sig,T){ return (Math.log(S/K)+(r-q+sig*sig/2)*T)/(sig*Math.sqrt(T)); }
function bs(S,K,r,q,sig,T,isCall){
  const d1=bsD1(S,K,r,q,sig,T), d2=d1-sig*Math.sqrt(T);
  const df=Math.exp(-r*T), qf=Math.exp(-q*T);
  return isCall ? S*qf*Phi(d1)-K*df*Phi(d2) : K*df*Phi(-d2)-S*qf*Phi(-d1);
}
function bsGreeks(S,K,r,q,sig,T,isCall){
  const sq=Math.sqrt(T), d1=bsD1(S,K,r,q,sig,T), d2=d1-sig*sq;
  const qf=Math.exp(-q*T), df=Math.exp(-r*T);
  const delta = isCall ? qf*Phi(d1) : qf*(Phi(d1)-1);
  const gamma = qf*phi(d1)/(S*sig*sq);
  const vega  = S*qf*phi(d1)*sq;                    /* per 1.00 of vol */
  const theta = (-S*qf*phi(d1)*sig/(2*sq)
               - (isCall? r*K*df*Phi(d2) : -r*K*df*Phi(-d2))
               + (isCall? q*S*qf*Phi(d1) : -q*S*qf*Phi(-d1)));  /* per year */
  const rho   = isCall ? K*T*df*Phi(d2) : -K*T*df*Phi(-d2);
  return {d1,d2,delta,gamma,vega,theta,rho};
}
/* Implied vol by bisection — no derivative needed, and monotone in sigma so
   bisection cannot fail to converge on the bracket. Note the genuine edge case:
   for a deeply in-the-money option the price equals discounted intrinsic to
   machine precision and vega is ~1e-30, so implied vol is not determined by the
   price at all. Bisection then returns the lower bracket, which is the smallest
   volatility consistent with the price — a defensible answer to an
   indeterminate question. Callers that care should check vega. */
function bsIV(price,S,K,r,q,T,isCall){
  let lo=1e-4, hi=5;
  for(let i=0;i<100;i++){ const m=(lo+hi)/2; (bs(S,K,r,q,m,T,isCall)<price? lo=m : hi=m); }
  return (lo+hi)/2;
}

/* ---------- misc finance ---------- */
function idmFor(n){ return n<=1?1.0:n<=2?1.2:n<=3?1.35:n<=4?1.5:n<=6?1.7:n<=8?2.0:n<=12?2.2:n<=20?2.4:2.5; }
function maxDD(series){ let peak=-Infinity, m=0; for(const v of series){ if(v>peak)peak=v; const d=(peak-v)/peak; if(d>m)m=d; } return m; }
function mean(a){ return a.reduce((s,x)=>s+x,0)/a.length; }
function sd(a,ddof){ const m=mean(a); const n=a.length-(ddof===undefined?1:ddof);
  return Math.sqrt(a.reduce((s,x)=>s+(x-m)*(x-m),0)/n); }
function corr(a,b){ const ma=mean(a), mb=mean(b);
  let sab=0,sa=0,sb=0; for(let i=0;i<a.length;i++){ const x=a[i]-ma,y=b[i]-mb; sab+=x*y; sa+=x*x; sb+=y*y; }
  return sab/Math.sqrt(sa*sb); }
/* portfolio vol for equal weights, common pairwise correlation */
function eqVol(sig,n,rho){ return sig*Math.sqrt((1+(n-1)*rho)/n); }
/* Expected max of N standard normals (Bailey–López de Prado) */
function eMaxN(N){ const g=0.5772156649;
  return (1-g)*Phinv(1-1/N)+g*Phinv(1-1/(N*Math.E)); }
/* Probabilistic Sharpe Ratio */
function psr(sr,srStar,n,skew,kurt){
  const num=(sr-srStar)*Math.sqrt(n-1);
  const den=Math.sqrt(1-skew*sr+(kurt-1)/4*sr*sr);
  return Phi(num/den);
}

/* ---------- formatting ---------- */
const money = v => (v<0?"−$":"$") + Math.abs(v).toLocaleString("en-US");
const f2 = (v,d) => { d = d===undefined?2:d;
  const s=v.toLocaleString("en-US",{minimumFractionDigits:d,maximumFractionDigits:d});
  return s==="-0"||/^-0\.0*$/.test(s) ? s.slice(1) : s; };
const pc = (v,d) => f2(v,d===undefined?1:d)+"%";
const sgn = v => v>=0?"+":"−";
/* significant-figure rounding, for estimation targets */
function sig(v,n){ if(v===0) return 0; const m=Math.pow(10,n-1-Math.floor(Math.log10(Math.abs(v)))); return Math.round(v*m)/m; }
/* nice round numbers so mental arithmetic is possible where intended */
function nice(R,lo,hi){ const cands=[]; for(let e=Math.floor(Math.log10(lo)); e<=Math.ceil(Math.log10(hi)); e++){
    [1,1.5,2,2.5,3,4,5,6,7.5,8].forEach(m=>{ const v=m*Math.pow(10,e); if(v>=lo&&v<=hi) cands.push(v); }); }
  return cands.length?pick(R,cands):Math.round((lo+hi)/2); }

/* ============================================================
   EXPRESSION EVALUATION — used by the answer box and by the
   formula bank. Recursive descent, no eval, and variable-aware
   so an expression can be tested against many random bindings.
   ============================================================ */
const FUNCS={
  sqrt:Math.sqrt, ln:Math.log, exp:Math.exp, abs:Math.abs,
  log:x=>Math.log(x)/Math.LN10, log10:x=>Math.log(x)/Math.LN10,
  sin:Math.sin, cos:Math.cos, tan:Math.tan,
  floor:Math.floor, ceil:Math.ceil, round:Math.round,
  min:Math.min, max:Math.max, pow:Math.pow,
  sign:Math.sign, tanh:Math.tanh,
  clip:(x,lo,hi)=>Math.min(Math.max(x,lo),hi),
  /* the normal distribution, so risk formulas can be written directly */
  ncdf:z=>Phi(z), nd:z=>phi(z), ninv:p=>Phinv(p)
};
const CONSTS={pi:Math.PI, e:Math.E};
function evalExpr(src, vars){
  /* Strip thousands separators only — a bare comma still separates function
     arguments, so "1,234" and "min(A,B)" must both work. */
  let t=String(src).replace(/[$\s]/g,"");
  for(let k=0;k<8;k++){ const u=t.replace(/(\d),(\d{3})(?!\d)/g,"$1$2"); if(u===t) break; t=u; }
  const s=t.replace(/×/g,"*").replace(/÷/g,"/")
    .replace(/−/g,"-").replace(/–/g,"-").replace(/√/g,"sqrt").replace(/·/g,"*");
  if(!s) return NaN;
  if(!/^[0-9a-zA-Z_.+\-*/^()%,]+$/.test(s)) return NaN;
  let i=0;
  function num(){
    const st=i; let dots=0;
    while(i<s.length && /[0-9.]/.test(s[i])){ if(s[i]==="." && ++dots>1) return NaN; i++; }
    if(i<s.length && /[eE]/.test(s[i]) && /[0-9+\-]/.test(s[i+1]||"")){ i++; if(/[+\-]/.test(s[i]))i++;
      while(i<s.length && /[0-9]/.test(s[i])) i++; }
    const v=parseFloat(s.slice(st,i));
    return isFinite(v)?v:NaN;
  }
  function ident(){ const st=i; while(i<s.length && /[a-zA-Z_0-9]/.test(s[i])) i++; return s.slice(st,i); }
  function primary(){
    if(i>=s.length) return NaN;
    const c=s[i];
    if(c==="("){ i++; const v=expr(); if(s[i]===")") i++; else return NaN; return v; }
    if(c==="-"){ i++; return -primary(); }
    if(c==="+"){ i++; return primary(); }
    if(/[0-9.]/.test(c)) return num();
    if(/[a-zA-Z_]/.test(c)){
      const nm=ident();
      if(s[i]==="("){ i++; const args=[expr()]; while(s[i]===","){ i++; args.push(expr()); }
        if(s[i]===")") i++; else return NaN;
        const f=FUNCS[nm.toLowerCase()]; return f?f.apply(null,args):NaN; }
      if(vars && vars[nm]!==undefined) return vars[nm];
      if(CONSTS[nm.toLowerCase()]!==undefined) return CONSTS[nm.toLowerCase()];
      return NaN;
    }
    return NaN;
  }
  function postfix(){ let v=primary();
    while(s[i]==="%"){ i++; v=v/100; }
    return v; }
  function power(){ const b=postfix(); if(s[i]==="^"){ i++; const e=power(); return Math.pow(b,e); } return b; }
  function term(){ let v=power();
    while(s[i]==="*"||s[i]==="/"){ const op=s[i]; i++; const r=power(); v = op==="*"? v*r : v/r; }
    return v; }
  function expr(){ let v=term();
    while(s[i]==="+"||s[i]==="-"){ const op=s[i]; i++; const r=term(); v = op==="+"? v+r : v-r; }
    return v; }
  const v=expr();
  if(i<s.length) return NaN;
  return v;
}
/* draw one consistent binding for a formula item */
function drawVars(item, R){
  for(let attempt=0; attempt<200; attempt++){
    const v={};
    item.vars.forEach(d=>{
      v[d.n] = d.pick ? pick(R,d.pick)
             : d.int ? ri(R,d.lo,d.hi,d.step||1)
             /* significant figures, not decimal places — a range like
                1e-7 to 1e-5 must not be rounded to zero */
             : sig(d.lo+R()*(d.hi-d.lo), d.sf||6);
    });
    if(!item.cons || item.cons(v)) return v;
  }
  return null;
}
/* Test a typed expression against many random bindings. A formula is only
   right if it is right everywhere — which is the whole point of asking for
   one instead of a number. */
function checkFormula(item, src, seed){
  const R=RNG(seed||12345);
  if(!String(src).trim()) return {ok:false, empty:true};
  let tested=0;
  for(let k=0;k<220;k++){
    const v=drawVars(item,R);
    if(!v) continue;
    const want=item.ref(v);
    if(!isFinite(want)) continue;
    const got=evalExpr(src,v);
    tested++;
    if(!isFinite(got)) return {ok:false, tested, fail:{v, got, want, why:"did not evaluate"}};
    const scale=Math.max(Math.abs(want),1e-9);
    if(Math.abs(got-want)/scale > 1e-6) return {ok:false, tested, fail:{v, got, want}};
  }
  return {ok:tested>0, tested};
}

root.TLIB = {RNG,pick,pickN,ri,rf,rsign,shuffle,rn,
  evalExpr,drawVars,checkFormula,FUNCS,CONSTS,
  erf,Phi,phi,Phinv,
  bsD1,bs,bsGreeks,bsIV,
  idmFor,maxDD,mean,sd,corr,eqVol,eMaxN,psr,
  money,f2,pc,sgn,sig,nice};
})(typeof window!=="undefined"?window:globalThis);
