/* P1_importguard.js */
/* ============================================================
   IMPORT GUARD, AND RECOVERY FROM A BROKEN SAVE.

   The import handler was:

       const p=JSON.parse(r.result); if(!p||typeof p!=="object") throw 0;
       S=Object.assign({}, S, p);
       ... saveNow();

   Anything that parses as JSON is adopted and written to storage
   immediately. A truncated download, the wrong file, or an export
   from a different tool therefore does not merely fail — it replaces
   the state, persists, and is restored on every subsequent load. The
   trainer is then bricked, and the reset button lives inside the very
   panel that now throws while rendering. For an app holding months of
   spaced-repetition history, "unrecoverable without clearing site
   data" is not an acceptable failure mode for choosing the wrong file
   in a picker.

   Three changes, none of which touch the engine:

     1. before the engine reads storage, validate what is there; if it
        is structurally broken, set it aside under a backup key and
        start clean rather than crashing on every load;
     2. intercept the import button and validate the file first,
        repairing what can be repaired, rejecting what cannot, and
        saying which;
     3. keep the pre-import state under a rollback key, so an import
        that turns out to be the wrong file is not the end of it.

   This module is spliced ahead of the engine, so step 1 runs before
   load() sees anything.
   ============================================================ */
(function(root){
"use strict";
if(typeof document==="undefined"||typeof localStorage==="undefined") return;
const KEY="trainer.v2", BROKEN="trainer.v2.broken", PREV="trainer.v2.prev";
const RESERVED={__proto__:1, constructor:1, prototype:1};

/* The app saves on unload:
       addEventListener("beforeunload", saveNow)
   so reloading into a freshly written state would let the outgoing
   page write its own in-memory state back over it on the way out, and
   the import would appear to do nothing at all. Once an import is
   committed, writes to the trainer's key are refused until the page
   is gone. Everything else still saves normally. */
let LOCKED=false;
try{
  const proto=(root.Storage&&root.Storage.prototype)||null;
  if(proto&&proto.setItem&&!proto.setItem.__lock){
    const orig=proto.setItem;
    const wrapped=function(k,v){ if(LOCKED&&k===KEY) return; return orig.call(this,k,v); };
    wrapped.__lock=1;
    proto.setItem=wrapped;
  }
}catch(e){}

/* ---- what a state object has to look like ---- */
const isObj=v=>v!==null&&typeof v==="object"&&!Array.isArray(v);
const isNum=v=>typeof v==="number"&&isFinite(v);

function strip(v, depth){                /* drop keys that would poison a prototype */
  depth=depth||0;
  if(depth>8||v===null||typeof v!=="object") return v;
  if(Array.isArray(v)) return v.map(x=>strip(x,depth+1));
  const out={};
  Object.keys(v).forEach(k=>{ if(!RESERVED[k]) out[k]=strip(v[k],depth+1); });
  return out;
}

/* Returns {state, dropped, why}. state is null when the object cannot
   be a trainer state at all; dropped counts repairs made along the way. */
function sanitise(raw){
  if(!isObj(raw)) return {state:null, why:"that file is not a progress export"};
  const o=strip(raw);
  let dropped=0;

  /* it must look like this trainer's state, not merely be valid JSON */
  const looksRight = isObj(o.sk) || Array.isArray(o.hist) || isNum(o.n);
  if(!looksRight) return {state:null, why:"that file does not contain trainer progress"};

  ["hist","journal","sessions"].forEach(k=>{
    if(o[k]===undefined) return;
    if(!Array.isArray(o[k])){ delete o[k]; dropped++; }
  });
  ["sk","ability","daily","settings"].forEach(k=>{
    if(o[k]===undefined) return;
    if(!isObj(o[k])){ delete o[k]; dropped++; }
  });
  ["n","streak","best","created","v"].forEach(k=>{
    if(o[k]===undefined) return;
    if(!isNum(o[k])){ delete o[k]; dropped++; }
  });

  /* per-item scheduling state: one malformed entry is enough to put a
     NaN into a due date and take an item out of the rotation for good,
     so drop entries rather than trusting them */
  if(isObj(o.sk)){
    const clean=Object.create(null);
    Object.keys(o.sk).forEach(id=>{
      const e=o.sk[id];
      if(!isObj(e)){ dropped++; return; }
      const ok=["s","d","due","last","reps","lapses","seen","ok"].every(f=>e[f]===undefined||isNum(e[f]));
      if(!ok){ dropped++; return; }
      clean[id]=e;
    });
    o.sk=JSON.parse(JSON.stringify(clean));
  }
  if(isObj(o.ability)){
    Object.keys(o.ability).forEach(d=>{ if(!isNum(o.ability[d])&&!isObj(o.ability[d])){ delete o.ability[d]; dropped++; } });
  }
  if(Array.isArray(o.hist)){
    const before=o.hist.length;
    o.hist=o.hist.filter(h=>isObj(h));
    dropped+=before-o.hist.length;
  }
  return {state:o, dropped:dropped, why:""};
}

/* ---- 1. recover a broken save before the engine reads it ---- */
let recovered=false;
try{
  const raw=localStorage.getItem(KEY);
  if(raw){
    let parsed=null, ok=true;
    try{ parsed=JSON.parse(raw); }catch(e){ ok=false; }
    if(ok){ const r=sanitise(parsed); if(!r.state) ok=false;
      else if(r.dropped){ localStorage.setItem(KEY, JSON.stringify(r.state)); } }
    if(!ok){
      try{ localStorage.setItem(BROKEN, raw); }catch(e){}
      localStorage.removeItem(KEY);
      recovered=true;
    }
  }
}catch(e){}

/* ---- shared banner, matching the save-health one ---- */
function styleOnce(){
  if(document.getElementById("svh-css")) return;
  const s=document.createElement("style"); s.id="svh-css";
  s.textContent=`
  #svh{display:flex;gap:10px;align-items:flex-start;
    padding:10px 14px;background:var(--warn-soft,#fdf3e3);color:var(--ink,#241f1a);
    border-bottom:1px solid var(--warn,#b7791f);font:14px/1.45 var(--sans,system-ui);}
  #svh b{font-weight:650}
  #svh .svh-t{flex:1;min-width:0}
  #svh .svh-s{display:block;color:var(--ink-2,#5b5249);font-size:13px;margin-top:2px}
  #svh button{flex:none;border:1px solid var(--rule-strong,#bdb3a6);background:var(--surface,#fff);
    color:inherit;border-radius:var(--r-sm,6px);padding:5px 10px;font:inherit;font-size:13px;cursor:pointer}
  #svh button:hover{background:var(--surface-2,#f4f1ec)}
  @media(max-width:560px){#svh{flex-wrap:wrap}#svh .svh-t{flex-basis:100%}}`;
  document.head.appendChild(s);
}
function banner(title, detail, actions){
  styleOnce();
  const old=document.getElementById("svh"); if(old) old.remove();
  const el=document.createElement("div"); el.id="svh"; el.setAttribute("role","alert");
  const t=document.createElement("div"); t.className="svh-t";
  const b=document.createElement("b"); b.textContent=title;
  const s=document.createElement("span"); s.className="svh-s"; s.textContent=detail;
  t.appendChild(b); t.appendChild(s); el.appendChild(t);
  (actions||[]).forEach(a=>{ const btn=document.createElement("button");
    btn.type="button"; btn.textContent=a[0]; btn.onclick=a[1]; el.appendChild(btn); });
  const dis=document.createElement("button"); dis.type="button";
  dis.textContent="Dismiss"; dis.onclick=()=>el.remove(); el.appendChild(dis);
  const main=document.querySelector("#tr-root main");
  if(main&&main.parentNode) main.parentNode.insertBefore(el, main);
  else document.body.insertBefore(el, document.body.firstChild);
}
function whenReady(fn){
  if(document.readyState==="loading") document.addEventListener("DOMContentLoaded",fn,{once:true});
  else setTimeout(fn,0);
}

if(recovered) whenReady(()=>banner(
  "Saved progress could not be read, so the trainer has started fresh.",
  "The unreadable copy has been kept in this browser rather than deleted, in case it can be salvaged. If you have an export file, use Import in Progress → Your data.",
  []));

/* ---- 2. confirm the import once the page has reloaded into it ---- */
function rollbackAction(){
  return ["Undo the import", ()=>{
    try{ const prev=localStorage.getItem(PREV);
      if(prev){ localStorage.setItem(KEY, prev); localStorage.removeItem(PREV);
        LOCKED=true; location.reload(); }
    }catch(e){}
  }];
}
try{
  const flag=sessionStorage.getItem("trainer.justImported");
  if(flag!==null){
    sessionStorage.removeItem("trainer.justImported");
    whenReady(()=>banner("Progress imported.",
      flag==="1" ? "The trainer has reloaded with the imported state. If this was the wrong file, undo it here."
                 : "The trainer has reloaded with the imported state.",
      flag==="1" ? [rollbackAction()] : []));
  }
}catch(e){}

/* ---- 3. intercept the import button ---- */

document.addEventListener("click", function(ev){
  const t=ev.target&&ev.target.closest?ev.target.closest("#imp"):null;
  if(!t) return;
  ev.preventDefault(); ev.stopImmediatePropagation();

  const f=document.createElement("input");
  f.type="file"; f.accept=".json,application/json";
  f.onchange=()=>{
    const file=f.files&&f.files[0]; if(!file) return;
    if(file.size>25*1024*1024){ alert("That file is far larger than a progress export. Nothing has been changed."); return; }
    const r=new FileReader();
    r.onerror=()=>alert("That file could not be read. Nothing has been changed.");
    r.onload=()=>{
      let parsed=null;
      try{ parsed=JSON.parse(r.result); }
      catch(e){ alert("That file is not valid JSON, so it has been ignored. Your progress is unchanged."); return; }
      const res=sanitise(parsed);
      if(!res.state){ alert("Import refused: "+res.why+". Your progress is unchanged."); return; }

      const items=res.state.sk?Object.keys(res.state.sk).length:0;
      const revs=Array.isArray(res.state.hist)?res.state.hist.length:0;
      let msg="Replace the progress in this browser with the file?\n\n"+
              items+" scheduled item"+(items===1?"":"s")+", "+revs+" recorded review"+(revs===1?"":"s")+".";
      if(res.dropped) msg+="\n\n"+res.dropped+" damaged entr"+(res.dropped===1?"y was":"ies were")+" dropped while reading it.";
      msg+="\n\nThe current state is kept so this can be undone.";
      window.__QC_ASK__(msg).then(function(ok){
      if(!ok) return;

      /* the rollback copy is a convenience; failing to write it must
         not stop an import the user asked for */
      let undoable=false;
      try{ const prev=localStorage.getItem(KEY);
        if(prev!==null){ localStorage.setItem(PREV, prev); undoable=true; } }catch(e){}
      try{ localStorage.setItem(KEY, JSON.stringify(res.state)); }
      catch(e){
        alert("The import could not be saved — this browser is refusing to store data. Your progress is unchanged.");
        return;
      }
      LOCKED=true;                       /* nothing may overwrite it on the way out */
      setTimeout(()=>{ LOCKED=false; }, 5000);   /* never leave saving off if the reload does not happen */
      try{ sessionStorage.setItem("trainer.justImported", undoable?"1":"0"); }catch(e){}
      setTimeout(()=>location.reload(), 60);
      });
    };
    r.readAsText(file);
  };
  f.click();
}, true);

root.TRAINER_IMPORT_GUARD=1;
root.TRAINER_RECOVERED=recovered;
root.TRAINER_SANITISE=sanitise;
})(typeof window!=="undefined"?window:globalThis);
