/* ============================================================
   THE TRAINER — engine
   Date-aware spaced repetition, adaptive difficulty, calibration,
   timing, and the analytics that make all three legible.
   ============================================================ */
(function(){
"use strict";
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const GENS=window.TRAINER_GENS||[], JUDGE=window.TRAINER_JUDGE||[], CARDS=window.TRAINER_CARDS||[];
const DERIVE=window.TRAINER_DERIVE||[], ESTIM=window.TRAINER_ESTIMATE||[], DESK=window.TRAINER_DESK||[];
const FORMULA=window.TRAINER_FORMULA||[], LABS=window.TRAINER_LAB||[];
const SEQ=window.TRAINER_SEQ||[], SPOT=window.TRAINER_SPOT||[], TUNE=window.TRAINER_TUNE||[];
const L=window.TLIB, RNG=L.RNG;
const KEY="trainer.v2", OLDKEY="trainer.v1";
const DAY=86400000;

/* ============================================================
   1. STATE
   ============================================================ */
const DEF_SETTINGS={conf:true, timer:true, autoAdv:false, adaptive:true, mix:"balanced", goal:20, ref:"Quant Trading.html", xref:true, commit:true};
let S={
  v:2, created:Date.now(), n:0, streak:0, best:0,
  sk:{},              /* per-item scheduling state */
  ability:{},         /* per-domain ability, drives difficulty tier */
  hist:[],            /* {t,key,kind,dom,ok,ms,conf,tier,el} — el = days since last review */
  journal:[],         /* replayable mistakes */
  sessions:[],        /* {t,n,ok,ms} */
  daily:{},           /* "YYYY-MM-DD" -> {n,ok,ms} — the habit, which is the real variable */
  settings:Object.assign({},DEF_SETTINGS),
  seenIntro:0
};
function load(){
  try{ const r=localStorage.getItem(KEY);
    if(r){ const p=JSON.parse(r); S=Object.assign(S,p); S.settings=Object.assign({},DEF_SETTINGS,p.settings||{}); return; }
  }catch(e){}
  /* migrate v1 (count-based Leitner) into date-based stability */
  try{ const r=localStorage.getItem(OLDKEY); if(!r) return;
    const o=JSON.parse(r); const BOXDAYS=[0.5,1,3,8,21,60];
    S.n=o.n||0; S.best=o.best||0; S.created=o.started||Date.now();
    Object.entries(o.sk||{}).forEach(([k,v])=>{
      S.sk[k]={s:BOXDAYS[Math.min(5,v.box||0)], d:5.5, due:Date.now(), last:Date.now()-DAY,
               reps:v.seen||0, lapses:0, seen:v.seen||0, ok:v.ok||0, susp:0};
    });
    S.migrated=1;
  }catch(e){}
}
let saveT=0;
function save(){ clearTimeout(saveT); saveT=setTimeout(()=>{
  try{ localStorage.setItem(KEY, JSON.stringify(S)); }catch(e){}
},120); }
function saveNow(){ clearTimeout(saveT); try{ localStorage.setItem(KEY, JSON.stringify(S)); }catch(e){} }
function sk(id){ return S.sk[id] || (S.sk[id]={s:0,d:5.5,due:0,last:0,reps:0,lapses:0,seen:0,ok:0,susp:0}); }

/* ============================================================
   2. EXPRESSION EVALUATION
   The answer box accepts arithmetic; the formula bank accepts
   expressions in named variables. Both live in the library so the
   test harness exercises exactly the code the page runs.
   ============================================================ */
const evalExpr=L.evalExpr, checkFormula=L.checkFormula, drawVars=L.drawVars;

/* ============================================================
   3. SCHEDULER — FSRS-lite, in real days
   Stability s = days at which recall probability falls to 90%.
   Difficulty d in [1,10]. Grade g in {1 again, 2 hard, 3 good, 4 easy}.
   ============================================================ */
const W={initS:[0.35,0.9,2.6,6.5], initD:[7.6,6.4,5.2,4.0], f:19/81, c:-0.5};
function retrievability(k, now){
  if(!k.reps||!k.last) return 0;
  const t=(now-k.last)/DAY;
  return Math.pow(1+W.f*t/Math.max(k.s,0.05), W.c);
}
function schedule(k, g, now){
  now=now||Date.now();
  if(!k.reps){
    k.s=W.initS[g-1]; k.d=W.initD[g-1];
  } else {
    const R=retrievability(k,now);
    /* difficulty drifts toward the grade, with mean reversion to 5 */
    k.d = Math.min(10, Math.max(1, k.d - 0.85*(g-3) + 0.06*(5-k.d)));
    if(g===1){
      k.lapses++;
      k.s = Math.max(0.25, 2.2 * Math.pow(k.d,-0.4) * Math.pow(k.s,0.28) * Math.exp(0.55*(1-R)));
      k.s = Math.min(k.s, k.s0===undefined? k.s : k.s0);
    } else {
      const hard = g===2?0.62:1, easy = g===4?1.35:1;
      const inc = Math.exp(0.9) * (11-k.d) * Math.pow(Math.max(k.s,0.05),-0.28)
                * (Math.exp(1.4*(1-R))-1) * hard * easy;
      k.s = Math.max(0.3, k.s * (1 + inc));
    }
  }
  k.s=Math.min(k.s, 1500);
  k.reps++; k.last=now;
  const fuzz = 1 + (Math.random()-0.5)*0.1;
  k.due = now + Math.max(0.2, k.s)*DAY*fuzz;
  return k;
}
/* grade an auto-marked answer from correctness and speed */
function gradeOf(ok, ms, target){
  if(!ok) return 1;
  if(!target) return 3;
  const r=ms/(target*1000);
  if(r<0.55) return 4;
  if(r>2.0) return 2;
  return 3;
}
function isLeech(k){ return k.lapses>=6 && k.seen>=8; }
function dayKey(d){ d=d||new Date(); 
  return d.getFullYear()+"-"+String(d.getMonth()+1).padStart(2,"0")+"-"+String(d.getDate()).padStart(2,"0"); }
function today(){ if(!S.daily) S.daily={};
  return S.daily[dayKey()] || (S.daily[dayKey()]={n:0,ok:0,ms:0}); }
function dayStreak(){
  if(!S.daily) return 0;
  const goal=S.settings.goal||20;
  let n=0, d=new Date();
  /* today only breaks the run once it is over; until then look back from yesterday */
  const t=S.daily[dayKey(d)];
  if(t && t.n>=goal) n++;
  for(let i=1;i<400;i++){
    d.setDate(d.getDate()-1);
    const e=S.daily[dayKey(d)];
    if(e && e.n>=goal) n++; else break;
  }
  return n;
}
function dueCount(now){
  now=now||Date.now();
  let n=0;
  POOL.forEach(p=>{ const k=S.sk[p.key]; if(k && !k.susp && k.reps && k.due<=now) n++; });
  return n;
}

/* ============================================================
   4. ABILITY / DIFFICULTY TIER
   ============================================================ */
function ability(dom){ if(S.ability[dom]===undefined) S.ability[dom]=0.30; return S.ability[dom]; }
function bumpAbility(dom, ok){
  const a=ability(dom);
  S.ability[dom] = ok ? a + 0.045*(1-a) : Math.max(0.05, a - 0.095*a);
}
function tierFor(dom){
  if(!S.settings.adaptive) return 0;
  const a=ability(dom);
  return a<0.45?0 : a<0.72?1 : 2;
}

/* ============================================================
   5. POOL
   ============================================================ */
const VOLDOM={"0":"Method","00":"Method","0A":"Mathematics","0B":"Tooling",
  "01":"Stochastic","02":"Mechanics","2A":"Mechanics","03":"Stat arb","04":"Statistics",
  "4A":"Statistics","05":"Factors","06":"Machine learning","07":"Machine learning","08":"Options",
  "8A":"Options","09":"Systems","10":"Execution","10A":"Execution","11":"Portfolio","11A":"Portfolio",
  "12":"Risk","12A":"Risk","13":"Strategies","13A":"Rates","14":"Crypto","15":"Data","16":"Data",
  "17":"Systems","18":"Rigour","19":"Business","19A":"Business","20":"Proofs","21":"Systems",
  "22":"Factors","23":"Probability","24":"Method","25":"Method","25A":"Method","26":"Method"};
const POOL=[];
GENS.forEach(g=>POOL.push({key:"g:"+g.id, kind:"calc", dom:g.dom, name:g.name, vol:g.vol, g,
  mental:(g.tags||[]).indexOf("mental")>=0, t:g.t}));
JUDGE.forEach((j,i)=>POOL.push({key:"j:"+i, kind:"judge", dom:j.dom, name:"Judgement", vol:j.vol, j, t:[45,55,70]}));
CARDS.forEach(c=>POOL.push({key:"c:"+c.i, kind:"recall", dom:VOLDOM[c.v]||"Method", name:"Volume "+c.v, vol:c.v, c, t:[30,35,45]}));
DERIVE.forEach(d=>POOL.push({key:"d:"+d.id, kind:"derive", dom:d.dom, name:d.name, vol:d.vol, d, t:d.t}));
ESTIM.forEach(e=>POOL.push({key:"e:"+e.id, kind:"estimate", dom:e.dom, name:e.name, vol:e.vol, e, t:e.t}));
DESK.forEach(k=>POOL.push({key:"k:"+k.id, kind:"desk", dom:k.dom, name:k.name, vol:k.vol, k, t:k.t}));
FORMULA.forEach(f=>POOL.push({key:"f:"+f.id, kind:"formula", dom:f.dom, name:f.name, vol:f.vol, f, t:f.t}));
LABS.forEach(b=>POOL.push({key:"b:"+b.id, kind:"lab", dom:b.dom, name:b.name, vol:b.vol, b, t:b.t}));
SEQ.forEach(q=>POOL.push({key:"q:"+q.id, kind:"sequence", dom:q.dom, name:q.name, vol:q.vol, q, t:q.t}));
SPOT.forEach(w=>POOL.push({key:"w:"+w.id, kind:"spot", dom:w.dom, name:w.name, vol:w.vol, w, t:w.t}));
TUNE.forEach(u=>POOL.push({key:"u:"+u.id, kind:"tune", dom:u.dom, name:u.name, vol:u.vol, u, t:u.t}));
const BYKEY={}; POOL.forEach(p=>BYKEY[p.key]=p);
const DOMAINS=[...new Set(POOL.map(p=>p.dom))].sort();
const KINDLBL={calc:"compute it", judge:"judge it", recall:"recall it",
  derive:"derive it", estimate:"estimate it", desk:"decide", formula:"generalise it", lab:"do it",
  sequence:"order it", spot:"spot the flaw", tune:"tune it"};
const KINDNAME={calc:"Compute", judge:"Judge", recall:"Recall", derive:"Derive",
  estimate:"Estimate", desk:"Desk", formula:"Formula", lab:"Lab",
  sequence:"Order", spot:"Spot", tune:"Tune"};
const KINDBLURB={
  calc:"Generated fresh every time, so nothing can be memorised — only worked out.",
  judge:"One defensible answer each; the distractors are beliefs people actually hold.",
  recall:"Self-graded, because producing a definition cannot be marked automatically.",
  derive:"Multi-step, marked step by step, with partial credit.",
  estimate:"Order-of-magnitude reasoning, graded on log error.",
  desk:"Sequential decisions where your choices carry forward.",
  formula:"Type the rule in symbols; it is tested against two hundred random inputs.",
  lab:"A working simulation. You make the decisions, then find out what was true.",
  sequence:"Put the steps in the order you would really do them. The order is the knowledge.",
  spot:"A protocol or a piece of code with something wrong in it. Find it before it costs you.",
  tune:"Move the controls until the objective is met. You feel the trade-off rather than reading about it."};

/* ============================================================
   6. SESSION
   ============================================================ */
const MIXES={
  balanced:{calc:.21,judge:.12,recall:.14,derive:.07,estimate:.06,desk:.06,formula:.11,lab:.04,
            sequence:.07,spot:.07,tune:.05},
  numbers: {calc:.52,formula:.22,derive:.12,estimate:.07,tune:.07},
  judgement:{judge:.36,desk:.22,recall:.10,lab:.08,spot:.16,sequence:.08},
  /* Doing: the modes where you produce something rather than pick something. */
  doing:   {lab:.22,formula:.14,derive:.13,desk:.11,sequence:.13,spot:.14,tune:.13},
  drill:   {calc:1},
  /* An exam is marked objectively, so the self-graded recall cards are left
     out of it — grading yourself under exam conditions measures nothing. */
  exam:    {calc:.34,judge:.22,estimate:.08,derive:.09,desk:.05,sequence:.08,spot:.09,tune:.05}
};
let MODE={kinds:null, dom:null, len:25, budgetMs:0, dueOnly:false, weak:false, speed:0, exam:false, mix:"balanced"};
let queue=[], idx=0, cur=null, phase="", sessionOk=0, sessionN=0, sessionScore=0, t0=0, startedAt=0;
let relearn=[], relearned=Object.create(null), tickT=0, examLog=[];

function eligible(){
  const now=Date.now();
  return POOL.filter(p=>{
    const k=S.sk[p.key];
    if(k&&k.susp) return false;
    if(MODE.vols && MODE.vols.indexOf(String(p.vol))<0) return false;
    if(MODE.dom && p.dom!==MODE.dom) return false;
    if(MODE.speed && !p.mental) return false;
    if(MODE.kinds && MODE.kinds.indexOf(p.kind)<0) return false;
    if(MODE.dueOnly && !(k && k.reps && k.due<=now)) return false;
    if(MODE.weak){ const a=S.ability[p.dom]; if(a!==undefined && a>0.6) return false; }
    return true;
  });
}
function priority(p, now){
  const k=S.sk[p.key];
  if(!k || !k.reps) return 620 + Math.random()*30;   /* unseen: below anything due, above anything ahead */
  if(k.due<=now){
    const overdueDays=Math.min(400,(now-k.due)/DAY);
    const R=retrievability(k,now);
    return 1000 + (1-R)*300 + Math.min(overdueDays,60)*2 + (isLeech(k)?120:0) + Math.random()*25;
  }
  /* not due: only used to top up. Prefer the least-well-known. */
  return 100 - retrievability(k,now)*80 - k.s*0.05 + Math.random()*20;
}
function buildQueue(){
  const now=Date.now();
  const pool=eligible();
  if(!pool.length) return [];
  const scored=pool.map(p=>({p, pr:priority(p,now)})).sort((a,b)=>b.pr-a.pr);
  const n=MODE.len;
  if(MODE.speed) return scored.slice(0,400).map(x=>x.p);

  /* target composition by kind */
  const mix=MIXES[MODE.mix]||MIXES.balanced;
  const kinds=[...new Set(scored.map(x=>x.p.kind))];
  const want={}; let tot=0;
  kinds.forEach(k=>{ want[k]=mix[k]||0; tot+=want[k]; });
  if(tot<=0){ kinds.forEach(k=>want[k]=1/kinds.length); tot=1; }
  const avail={}; kinds.forEach(k=>avail[k]=scored.filter(x=>x.p.kind===k).length);
  kinds.forEach(k=>{ want[k]=Math.min(avail[k], Math.round(n*want[k]/tot)); });
  let sum=kinds.reduce((s,k)=>s+want[k],0);
  /* top up in priority order of availability */
  let guard=0;
  while(sum<Math.min(n,pool.length) && guard++<200){
    let added=false;
    for(const k of kinds){ if(want[k]<avail[k]){ want[k]++; sum++; added=true; if(sum>=n) break; } }
    if(!added) break;
  }

  /* interleave: avoid consecutive same domain, then same kind */
  const out=[], taken={}; kinds.forEach(k=>taken[k]=0);
  const pot=scored.slice();
  let lastDom=null, lastKind=null;
  while(out.length<n && pot.length){
    const fits=x=>taken[x.p.kind]<want[x.p.kind];
    let i=pot.findIndex(x=>fits(x)&&x.p.dom!==lastDom&&x.p.kind!==lastKind);
    if(i<0) i=pot.findIndex(x=>fits(x)&&x.p.dom!==lastDom);
    if(i<0) i=pot.findIndex(x=>fits(x)&&x.p.kind!==lastKind);
    if(i<0) i=pot.findIndex(fits);
    if(i<0) break;
    const x=pot.splice(i,1)[0];
    taken[x.p.kind]++; lastDom=x.p.dom; lastKind=x.p.kind; out.push(x.p);
  }
  return out;
}

/* ============================================================
   7. RENDER HELPERS
   ============================================================ */
function esc(s){ return String(s).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;"); }
function fmtNum(x){
  if(!isFinite(x)) return String(x);
  const a=Math.abs(x);
  if(a===0) return "0";
  if(a<0.0005 || a>=1e12) return x.toExponential(3).replace("e","e");
  if(a<1){
    /* three significant figures, trailing zeros trimmed — 0.002 not 0.00200 */
    const s=x.toPrecision(3);
    return s.indexOf(".")>=0 ? s.replace(/0+$/,"").replace(/\.$/,"") : s;
  }
  const d = a>=1000?0 : a>=100?1 : 2;
  return x.toLocaleString("en-US",{minimumFractionDigits:0,maximumFractionDigits:d});
}
/* Units attach differently: "12%" and "12×" take no space, "$" is a prefix,
   and "12 bp" takes one. Getting this wrong reads as sloppiness on every
   single answer, so it is worth the eight lines. */
function withUnit(v, unit){
  const n=fmtNum(v);
  if(!unit) return "<b>"+n+"</b>";
  if(unit==="%"||unit==="×"||unit==="σ") return "<b>"+n+unit+"</b>";
  if(unit==="$") return "<b>"+(v<0?"−$"+fmtNum(-v):"$"+n)+"</b>";
  if(unit==="$m") return "<b>"+(v<0?"−$"+fmtNum(-v):"$"+n)+"m</b>";
  if(unit==="$/day") return "<b>"+(v<0?"−$"+fmtNum(-v):"$"+n)+"</b>/day";
  return "<b>"+n+"</b> "+esc(unit);
}
function fmtDur(ms){
  const s=ms/1000;
  if(s<60) return s.toFixed(1)+"s";
  if(s<3600) return Math.floor(s/60)+"m "+Math.round(s%60)+"s";
  return (s/3600).toFixed(1)+"h";
}
function fmtDays(d){
  if(d<1) return Math.round(d*24)+"h";
  if(d<60) return Math.round(d)+"d";
  if(d<730) return (d/30.4).toFixed(1)+"mo";
  return (d/365).toFixed(1)+"y";
}
const XREF=window.TRAINER_XREF||{sec:{},vol:{},titles:{}};
function xrefHref(vol){
  if(!S.settings.xref || !S.settings.ref) return null;
  const anchor = XREF.sec[String(vol)] || XREF.vol[String(vol).split(".")[0]];
  if(!anchor) return null;
  return encodeURI(S.settings.ref)+"#"+anchor;
}
function xrefLink(p){
  if(!p.vol) return "";
  const label="Volume "+esc(p.vol)+(p.name?" &middot; "+esc(p.name):"");
  const href=xrefHref(p.vol);
  const vt=XREF.titles?XREF.titles[String(p.vol).split(".")[0]]:null;
  return href
    ? `<div class="xref">Reference &middot; <a href="${href}" target="_blank" rel="noopener"${vt?` title="${esc(vt)}"`:""}>${label}</a> &nearr;</div>`
    : `<div class="xref">Reference &middot; ${label}</div>`;
}
function targetSec(p){
  const t=p.t;
  if(Array.isArray(t)) return t[Math.min(2,tierFor(p.dom))];
  return {calc:50,judge:50,recall:32,derive:240,estimate:110,desk:300}[p.kind]||50;
}
function itemTag(p, extra){
  const k=S.sk[p.key];
  const now=Date.now();
  const state = !k||!k.reps ? '<span class="new">new</span>'
    : (k.due<=now ? '<span class="due">due</span>' : '<span>ahead</span>');
  const leech = k&&isLeech(k) ? '<span class="leech">leech</span>' : "";
  const tier=tierFor(p.dom);
  const tierLbl = (p.kind==="calc"&&S.settings.adaptive) ?
    `<span class="tier">${["core","stretch","hard"][tier]}</span>` : "";
  const clock = S.settings.timer ?
    `<div class="clock" id="clk"><i><b id="clkbar"></b></i><span id="clkt" style="background:none;padding:0;letter-spacing:0;text-transform:none;font-family:var(--mono)">0.0s</span></div>` : "";
  return `<div class="tag"><span class="dom">${esc(p.dom)}</span><span class="kind">${KINDLBL[p.kind]}</span>${state}${leech}${tierLbl}${extra||""}${clock}</div>`;
}
function startClock(p){
  clearInterval(tickT);
  if(!S.settings.timer) return;
  const target=targetSec(p)*1000;
  tickT=setInterval(()=>{
    const el=Date.now()-t0;
    const bar=$("#clkbar"), txt=$("#clkt"), box=$("#clk");
    if(!bar){ clearInterval(tickT); return; }
    const frac=Math.min(1, el/target);
    bar.style.right=(100-frac*100)+"%";
    txt.textContent=(el/1000).toFixed(1)+"s";
    if(el>target) box.classList.add("over"); else box.classList.remove("over");
  },100);
}
function stopClock(){ clearInterval(tickT); }

/* ============================================================
   8. MARKING
   ============================================================ */
let lastRecord=null;
function record(p, ok, ms, conf, grade, note){
  const k=sk(p.key);
  lastRecord={key:p.key, dom:p.dom, snap:JSON.parse(JSON.stringify(k)),
    histLen:S.hist.length, journalLen:S.journal.length,
    ability:S.ability[p.dom], n:S.n, streak:S.streak, best:S.best,
    sessionN:sessionN, sessionOk:sessionOk, day:JSON.parse(JSON.stringify(today()))};
  const el = k.last ? (Date.now()-k.last)/DAY : null;
  k.seen++; if(ok) k.ok++;
  if(k.s0===undefined) k.s0=k.s;
  schedule(k, grade, Date.now());
  bumpAbility(p.dom, ok);
  S.n++;
  S.hist.push({t:Date.now(), key:p.key, kind:p.kind, dom:p.dom, ok:ok?1:0,
    ms:ms, conf:conf||null, el:el===null?null:Math.round(el*100)/100});
  if(S.hist.length>8000) S.hist=S.hist.slice(-6000);
  S.streak = ok ? S.streak+1 : 0;
  S.best = Math.max(S.best, S.streak);
  sessionN++; if(ok) sessionOk++;
  const td=today(); td.n++; if(ok) td.ok++; td.ms+=ms||0;
  if(!ok && note){
    S.journal.unshift(Object.assign({t:Date.now(), key:p.key, kind:p.kind, dom:p.dom, name:p.name}, note));
    if(S.journal.length>250) S.journal.length=250;
  }
  save(); updateBar();
}
function undoLast(){
  /* a mis-keyed answer should not be allowed to wreck a schedule — restore
     everything the record touched and re-ask the same item. */
  if(!lastRecord) return false;
  const r=lastRecord; lastRecord=null;
  S.sk[r.key]=r.snap;
  S.hist.length=r.histLen;
  S.journal.length=r.journalLen;
  if(r.ability===undefined) delete S.ability[r.dom]; else S.ability[r.dom]=r.ability;
  S.n=r.n; S.streak=r.streak; S.best=r.best;
  sessionN=r.sessionN; sessionOk=r.sessionOk;
  S.daily[dayKey()]=r.day;
  relearned[r.key]=0;
  const ri2=relearn.indexOf(BYKEY[r.key]); if(ri2>=0) relearn.splice(ri2,1);
  saveNow(); updateBar();
  return true;
}
function updateBar(){
  const tot=S.hist.length, ok=S.hist.reduce((s,h)=>s+h.ok,0);
  const d=dueCount();
  const life=$("#life"), acc=$("#acc"), str=$("#str"), duep=$("#duepill"),
        todp=$("#todaypill"), runp=$("#runpill");
  if(life) life.innerHTML="<b>"+tot.toLocaleString("en-US")+"</b> done";
  if(acc) acc.innerHTML="<b>"+(tot?Math.round(ok/tot*100):0)+"%</b> right";
  if(str) str.innerHTML="<b>"+S.streak+"</b> streak";
  if(duep){ duep.innerHTML="<b>"+d+"</b> due"; duep.classList.toggle("due-hot", d>0); }
  const goal=S.settings.goal||20, td=today(), run=dayStreak();
  if(todp){ todp.innerHTML="<b>"+td.n+"</b>/"+goal+" today"; todp.classList.toggle("due-hot", td.n<goal); }
  if(runp){ runp.innerHTML="<b>"+run+"</b> day run"; runp.style.display = run>0?"":"none"; }
}

/* ---- confidence gate ---- */
let pendingConf=null;
const CONF=[{v:0.5,l:"Guess"},{v:0.65,l:"Leaning"},{v:0.8,l:"Fairly sure"},{v:0.9,l:"Confident"},{v:0.98,l:"Certain"}];
function askConfidence(cb){
  if(!S.settings.conf){ cb(null); return; }
  pendingConf=cb; phase="conf";
  const host=$("#fb"); if(!host){ cb(null); return; }
  host.innerHTML=`<div class="confbox fadein"><div class="lbl">Before you see the answer — how sure are you?</div>
    <div class="confrow">${CONF.map((c,i)=>`<button class="cf" data-c="${i}"><b>${Math.round(c.v*100)}%</b><span>${c.l}</span><kbd style="display:block;margin-top:5px">${i+1}</kbd></button>`).join("")}</div></div>`;
  $$(".confrow .cf").forEach(b=>b.onclick=()=>pickConf(+b.dataset.c));
  const f=$(".confrow .cf"); if(f) f.focus();
}
function pickConf(i){
  if(phase!=="conf"||!pendingConf) return;
  const cb=pendingConf; pendingConf=null; phase="";
  cb(CONF[i].v);
}
function confBadge(conf, ok){
  if(conf==null) return "";
  const b=Math.pow(conf-(ok?1:0),2);
  const cls = b<0.06?"good" : b<0.2?"mid" : "bad";
  return `<span class="badge ${cls}">said ${Math.round(conf*100)}% &middot; brier ${b.toFixed(2)}</span>`;
}

/* ============================================================
   9. ITEM RENDERERS
   ============================================================ */
function render(){
  stopClock();
  if(idx>=queue.length){
    if(relearn.length){ queue=queue.concat(relearn.splice(0, relearn.length)); }
    else return renderDone();
  }
  if(MODE.budgetMs && Date.now()-startedAt>MODE.budgetMs) return renderDone();
  const p=queue[idx]; phase="answer"; cur={p};
  const seed=(Date.now()^(idx*2654435761)^(S.n*40503))>>>0;
  const tier=tierFor(p.dom);
  let body="";
  if(p.kind==="calc"){
    const o=p.g.gen(RNG(seed), tier); cur.o=o; cur.tier=tier;
    body=itemTag(p)+`<p class="q">${o.q}</p>
      <div class="ansrow"><input class="num" id="ans" inputmode="text" autocomplete="off" autocorrect="off"
        spellcheck="false" placeholder="answer or 2500/12.5">
        <span class="unit">${esc(o.unit||"")}</span>
        <button class="btn on" id="check">Check&nbsp; <kbd>&crarr;</kbd></button>
        ${o.hint&&!MODE.exam?'<button class="btn ghost sm" id="hintb">Hint <kbd>h</kbd></button>':""}</div>
      <div class="evalhint" id="ev"></div><div id="fb" aria-live="polite"></div>`;
  } else if(p.kind==="estimate"){
    const o=p.e.gen(RNG(seed)); cur.o=o;
    body=itemTag(p)+`<p class="q">${o.q}</p>
      <div class="ansrow"><input class="num" id="ans" inputmode="text" autocomplete="off"
        spellcheck="false" placeholder="e.g. 4e9 or 4000*1e6">
        <span class="unit">${esc(o.unit||"")}</span>
        <button class="btn on" id="check">Check&nbsp; <kbd>&crarr;</kbd></button></div>
      <div class="evalhint" id="ev"></div>
      <p class="hint" style="margin-top:2px">Graded on order of magnitude: within 2× is excellent, within 10× is passing.</p>
      <div id="fb" aria-live="polite"></div>`;
  } else if(p.kind==="judge"){
    const opts=L.shuffle(RNG(seed||1), p.j.opts.map((t,i)=>({t, ok:i===p.j.correct})));
    cur.opts=opts;
    body=itemTag(p)+`<p class="q">${p.j.q}</p><div class="opts" id="opts">`+
      opts.map((o,i)=>`<button class="opt" data-i="${i}"><kbd>${i+1}</kbd><span>${o.t}</span></button>`).join("")+
      `</div><div id="fb" aria-live="polite"></div>`;
  } else if(p.kind==="recall"){
    body=itemTag(p)+`<p class="q">${p.c.q}</p>
      ${S.settings.commit?`<div class="commit">
        <textarea id="commit" rows="2" spellcheck="false" placeholder="Say it in a line before you look — then reveal."></textarea>
      </div>`:""}
      <div class="ansrow"><button class="btn on" id="reveal">Reveal&nbsp; <kbd>space</kbd></button>
      <span class="unit">${S.settings.commit?"Writing it down first is what turns recognition into recall. <kbd>&crarr;</kbd> when you are done, or <kbd>space</kbd> on an empty box to skip it.":"Produce it out loud first — the attempt is the mechanism."}</span></div>
      <div id="fb" aria-live="polite"></div>`;
  } else if(p.kind==="derive"){
    const o=p.d.gen(RNG(seed)); cur.o=o; cur.step=0; cur.results=[];
    body=itemTag(p)+`<div class="stem">${o.stem}</div><div class="steps" id="steps"></div><div id="fb" aria-live="polite"></div>`;
  } else if(p.kind==="desk"){
    const o=p.k.gen(RNG(seed)); cur.o=o; cur.round=0; cur.scores=[];
    body=itemTag(p)+`<div class="stem">${o.brief}</div><div id="rounds"></div><div id="fb" aria-live="polite"></div>`;
  } else if(p.kind==="formula"){
    const f=p.f; cur.o=f;
    body=itemTag(p)+`<p class="q">Give an expression for <b>${f.ask}</b>.</p>
      <div class="symtab"><table class="st"><thead><tr><th>symbol</th><th>meaning</th><th>units</th></tr></thead><tbody>
      ${f.vars.map(v=>`<tr><td><code class="sym">${esc(v.n)}</code></td><td>${esc(v.d)}</td><td class="dim">${esc(v.u||"")}</td></tr>`).join("")}
      </tbody></table></div>
      <div class="ansrow"><input class="num wide" id="ans" inputmode="text" autocomplete="off" autocorrect="off"
        autocapitalize="off" spellcheck="false" placeholder="an expression in the symbols above">
        <button class="btn on" id="check">Check&nbsp; <kbd>&crarr;</kbd></button>
        ${f.hint&&!MODE.exam?'<button class="btn ghost sm" id="hintb">Hint <kbd>h</kbd></button>':""}</div>
      <p class="hint" style="margin-top:2px">Tested against 200 random values of every symbol, so a formula that fits one example will not pass.
        Available: <code>+ − × ÷ ^ ( )</code>, <code>sqrt ln exp abs min max</code>, and <code>ncdf nd ninv</code> for the normal distribution.</p>
      <div id="fb" aria-live="polite"></div>`;
  } else if(p.kind==="lab"){
    const o=p.b.gen(RNG(seed)); cur.o=o; cur.labDone=false;
    body=itemTag(p)+`<div class="labtitle">${esc(o.title)}</div><div class="stem">${o.brief}</div>
      <div class="labhost" id="labhost"></div><div id="fb" aria-live="polite"></div>`;
  } else if(p.kind==="sequence"){
    const o=p.q.gen(RNG(seed)); cur.o=o;
    /* present in a shuffled order; the correct order is the array order */
    cur.order=L.shuffle(RNG(seed||7), o.steps.map((st,i)=>i));
    cur.placed=[];
    body=itemTag(p)+`<div class="stem">${o.stem}</div><div class="seqwrap" id="seqwrap"></div>
      <div id="fb" aria-live="polite"></div>`;
  } else if(p.kind==="spot"){
    const o=p.w.gen(RNG(seed)); cur.o=o; cur.picks={};
    const nbad=o.lines.filter(l=>l.bad).length;
    cur.nbad=nbad;
    body=itemTag(p)+`<div class="stem">${o.stem}</div>
      <p class="spotcount">Click every line that is wrong. There ${nbad===1?"is <b>one</b>":"are <b>"+nbad+"</b>"} of them.</p>
      <div class="spotwrap${o.mono?" mono":""}" id="spotwrap">`+
      o.lines.map((l,i)=>`<div class="spotline" data-i="${i}"><span class="ln">${i+1}</span><span class="lt">${o.mono?esc(l.t):l.t}</span></div>`).join("")+
      `</div>
      <div class="ansrow"><button class="btn on" id="check">Check&nbsp; <kbd>&crarr;</kbd></button>
        <span class="unit" id="spotsel">nothing selected</span></div>
      <div id="fb" aria-live="polite"></div>`;
  } else if(p.kind==="tune"){
    const o=p.u.gen(RNG(seed)); cur.o=o;
    cur.vals={}; o.controls.forEach(c=>cur.vals[c.n]= c.init!==undefined?c.init:(c.lo+c.hi)/2);
    body=itemTag(p)+`<div class="stem">${o.stem}</div>
      <div class="tunegoal"><b>Your objective.</b> ${o.goal}</div>
      <div class="labgrid" id="tunectl"></div>
      <div id="tunelive"></div>
      <div class="ansrow" style="margin-top:10px"><button class="btn on" id="check">Lock it in&nbsp; <kbd>&crarr;</kbd></button>
        ${o.hint?'<button class="btn ghost sm" id="hintb">Hint <kbd>h</kbd></button>':""}</div>
      <div id="fb" aria-live="polite"></div>`;
  }
  $("#stage").innerHTML='<div class="card-wrap fadein">'+body+'</div>';
  $("#prog").style.width=(idx/Math.max(queue.length,1)*100).toFixed(1)+"%";
  const cnt=$("#cnt"); if(cnt) cnt.textContent=(idx+1)+" / "+queue.length;
  t0=Date.now(); startClock(p);

  const inp=$("#ans");
  if(inp){ inp.focus(); inp.addEventListener("input",showEval); }
  const cb=$("#commit");
  if(cb){ cb.focus(); cb.addEventListener("keydown", e=>{
    if(e.key==="Enter" && !e.shiftKey){ e.preventDefault(); revealCard(); return; }
    /* The card says space skips the box, and while the box has focus the global
       key handler never sees the key. On an empty box a space is not meaningful
       input, so honour the documented shortcut here. */
    if(e.key===" " && !cb.value){ e.preventDefault(); revealCard(); } }); }
  if($("#check")) $("#check").onclick = p.kind==="formula" ? submitFormula : submitNum;
  if($("#hintb")) $("#hintb").onclick=showHint;
  if($("#reveal")) $("#reveal").onclick=revealCard;
  $$("#opts .opt").forEach(b=>b.onclick=()=>chooseOpt(+b.dataset.i));
  if(p.kind==="derive") renderSteps();
  if(p.kind==="sequence") renderSeq();
  if(p.kind==="spot") wireSpot();
  if(p.kind==="tune") wireTune();
  if(p.kind==="desk") renderRound();
  if(p.kind==="formula"){ const a=$("#ans"); if(a){ a.focus(); a.addEventListener("input",showFormulaEcho); } }
  if(p.kind==="lab") mountLab();
}

function showEval(){
  const el=$("#ev"), inp=$("#ans"); if(!el||!inp) return;
  const raw=inp.value.trim();
  if(!raw || /^-?[0-9.]+$/.test(raw)){ el.textContent=""; inp.classList.remove("bad"); return; }
  const v=evalExpr(raw);
  if(isFinite(v)){ el.textContent="= "+fmtNum(v); inp.classList.remove("bad"); }
  else { el.textContent="…"; inp.classList.add("bad"); }
}
function showFormulaEcho(){
  /* echo a sample evaluation as you type, so a typo is visible before you submit */
  const el=$("#ev")||(()=>{ const d=document.createElement("div"); d.className="evalhint"; d.id="ev";
    const r=$(".ansrow"); if(r&&r.parentNode) r.parentNode.insertBefore(d, r.nextSibling); return d; })();
  const inp=$("#ans"); if(!inp||!cur||!cur.o||!cur.o.vars) return;
  const raw=inp.value.trim();
  if(!raw){ el.textContent=""; inp.classList.remove("bad"); return; }
  const v=drawVars(cur.o, RNG(7)); if(!v){ el.textContent=""; return; }
  const got=evalExpr(raw, v);
  if(isFinite(got)){
    el.innerHTML="with "+Object.keys(v).map(k=>k+" = "+fmtNum(v[k])).join(", ")+" your expression gives <b>"+fmtNum(got)+"</b>";
    inp.classList.remove("bad");
  } else { el.textContent="…"; inp.classList.add("bad"); }
}
function submitFormula(){
  if(phase!=="answer") return;
  const inp=$("#ans"); if(!inp) return;
  const raw=(inp.value||"").trim();
  if(!raw){ inp.focus(); return; }
  cur.raw=raw; cur.ms=Date.now()-t0; stopClock();
  inp.disabled=true; const c=$("#check"); if(c) c.disabled=true;
  const hb=$("#hintb"); if(hb) hb.disabled=true;
  askConfidence(conf=>markFormula(conf));
}
function markFormula(conf){
  const p=cur.p, f=cur.o;
  const res=checkFormula(f, cur.raw, (Date.now()&0xffff)+1);
  const ok=res.ok;
  let extra;
  if(ok){
    extra=`<div>Your expression <code class="sym">${esc(cur.raw)}</code> matched on all <b>${res.tested}</b> random inputs.</div>`;
  } else if(res.fail){
    const v=res.fail.v;
    extra=`<div>It failed on the ${res.tested===1?"first":"<b>"+res.tested+"</b>th"} test.<br>
      With ${Object.keys(v).map(k=>`<code class="sym">${esc(k)}</code> = ${fmtNum(v[k])}`).join(", ")}<br>
      yours gives <b>${fmtNum(res.fail.got)}</b>, the answer is <b>${fmtNum(res.fail.want)}</b>.</div>`;
  } else {
    extra=`<div>That did not evaluate. Check the brackets and the symbol names.</div>`;
  }
  const grade=gradeOf(ok, cur.ms, targetSec(p));
  record(p, ok, cur.ms, conf, ok&&cur.usedHint&&grade>3?3:grade,
    ok?null:{q:"Express: "+f.ask, sol:`<b>${esc(f.answer)}</b><br>`+f.sol, yours:cur.raw, correct:f.answer, unit:""});
  if(!ok) requeue(p);
  showFeedback(ok, ok?"Correct — and general":"Not the rule", extra,
    `<div class="canon">One correct form: <code class="sym">${esc(f.answer)}</code></div>`+f.sol, conf, grade);
}

/* ---------- labs ---------- */
let labKeyFn=null;
function mountLab(){
  const host=$("#labhost"); if(!host) return;
  phase="lab"; labKeyFn=null;
  const api={
    done(res){ finishLab(res); },
    keys(fn){ labKeyFn=fn; }
  };
  try{ cur.o.mount(host, api); }
  catch(e){ host.innerHTML='<p class="empty">This lab could not start.</p>'; finishLab({score:0,max:1,summary:"",verdict:""}); }
}
function finishLab(res){
  if(cur.labDone) return;
  cur.labDone=true; labKeyFn=null; stopClock();
  cur.ms=Date.now()-t0;
  const frac=res.max? Math.max(0,res.score)/res.max : 0;
  const ok=frac>=0.7;
  const grade = frac>=0.95?4 : frac>=0.7?3 : frac>=0.4?2 : 1;
  record(cur.p, ok, cur.ms, null, grade, ok?null:{q:cur.o.title,
    sol:res.summary||"", yours:res.score+" of "+res.max, correct:res.max+" of "+res.max, unit:""});
  if(!ok) requeue(cur.p);
  const hostEl=$("#labhost"); if(hostEl) hostEl.innerHTML="";
  showFeedback(ok, `${res.score} of ${res.max}${res.verdict?" — "+res.verdict:""}`, "",
    res.summary||"", null, grade, frac>=0.7?"ok":frac>=0.4?"mid":"no");
}


/* ---------------- order it ---------------- */
function renderSeq(){
  const host=$("#seqwrap"); if(!host) return;
  const o=cur.o, n=o.steps.length, done=cur.placed.length===n;
  let h=`<div class="seqlbl">Your order</div>
    <div class="seqslots${cur.placed.length?"":" empty"}">`;
  cur.placed.forEach((si,pos)=>{
    h+=`<div class="seqrow"><b class="sn">${pos+1}</b><span>${o.steps[si].t}</span>
      <button class="sx" data-pos="${pos}" title="Take it back out">&times;</button></div>`;
  });
  h+=`</div>`;
  if(!done){
    h+=`<div class="seqlbl">Remaining &mdash; ${n-cur.placed.length} to place</div><div class="seqpool">`;
    cur.order.forEach((si,k)=>{
      if(cur.placed.indexOf(si)>=0) return;
      h+=`<button class="seqopt" data-si="${si}">${k<9?`<kbd>${k+1}</kbd>`:""}<span>${o.steps[si].t}</span></button>`;
    });
    h+=`</div>`;
  } else {
    h+=`<div class="ansrow" style="margin-top:12px"><button class="btn on" id="check">Check the order&nbsp; <kbd>&crarr;</kbd></button>
      <button class="btn ghost sm" id="seqclr">Start over</button></div>`;
  }
  host.innerHTML=h;
  host.querySelectorAll(".seqopt").forEach(b=>b.onclick=()=>{
    cur.placed.push(+b.dataset.si); renderSeq(); });
  host.querySelectorAll(".seqrow .sx").forEach(b=>b.onclick=()=>{
    cur.placed.splice(+b.dataset.pos,1); renderSeq(); });
  const cb=$("#check"); if(cb) cb.onclick=submitSeq;
  const cl=$("#seqclr"); if(cl) cl.onclick=()=>{ cur.placed=[]; renderSeq(); };
}
function submitSeq(){
  if(phase!=="answer") return;
  const o=cur.o, n=o.steps.length;
  if(cur.placed.length<n) return;
  stopClock(); cur.ms=Date.now()-t0;
  let exact=0;
  cur.placed.forEach((si,pos)=>{ if(si===pos) exact++; });
  /* partial credit also for getting the relative order right, which is the
     real skill: an inserted step early on should not zero everything after it */
  let pairs=0, tot=0;
  for(let a=0;a<n;a++) for(let b=a+1;b<n;b++){
    tot++;
    if(cur.placed.indexOf(a)<cur.placed.indexOf(b)) pairs++;
  }
  const pairFrac = tot? pairs/tot : 1;
  const frac = exact===n ? 1 : Math.max(0, (exact/n)*0.4 + pairFrac*0.6);
  const ok = exact===n;
  const grade = exact===n?4 : frac>=0.85?3 : frac>=0.6?2 : 1;
  let sol=`<div class="seqslots" style="background:none;border:none;padding:0">`;
  o.steps.forEach((st,i)=>{
    const yours=cur.placed.indexOf(i);
    const cls = yours===i ? "good" : "bad";
    sol+=`<div class="seqrow ${cls}"><b class="sn">${i+1}</b><span>${st.t}
      ${yours===i?"":`<em style="color:var(--neg)">You put this at ${yours+1}.</em>`}
      ${st.why?`<em>${st.why}</em>`:""}</span></div>`;
  });
  sol+=`</div>${o.close?`<p style="margin:12px 0 0">${o.close}</p>`:""}`;
  record(cur.p, ok, cur.ms, null, grade, ok?null:{q:o.stem,
    sol:sol, yours:exact+" of "+n+" in place", correct:n+" of "+n, unit:""});
  if(!ok) requeue(cur.p);
  showFeedback(ok, `${exact} of ${n} steps in the right place`, "", sol, null, grade,
    ok?"ok":frac>=0.6?"mid":"no");
}

/* ---------------- spot the flaw ---------------- */
function wireSpot(){
  const host=$("#spotwrap"); if(!host) return;
  host.querySelectorAll(".spotline").forEach(el=>el.onclick=()=>{
    if(phase!=="answer") return;
    const i=+el.dataset.i;
    cur.picks[i]=!cur.picks[i];
    el.classList.toggle("pick", !!cur.picks[i]);
    const n=Object.values(cur.picks).filter(Boolean).length;
    const lbl=$("#spotsel");
    if(lbl) lbl.textContent = n===0 ? "nothing selected"
      : n+" line"+(n>1?"s":"")+" selected"+(n===cur.nbad?"":" — you want "+cur.nbad);
  });
  const cb=$("#check"); if(cb) cb.onclick=submitSpot;
}
function submitSpot(){
  if(phase!=="answer") return;
  const o=cur.o;
  const picked=o.lines.map((l,i)=>!!cur.picks[i]);
  if(!picked.some(Boolean)) return;
  stopClock(); cur.ms=Date.now()-t0;
  let hit=0, fp=0;
  o.lines.forEach((l,i)=>{ if(l.bad&&picked[i]) hit++; if(!l.bad&&picked[i]) fp++; });
  const nbad=cur.nbad;
  const frac=Math.max(0,(hit-fp*0.75)/nbad);
  const ok = hit===nbad && fp===0;
  const grade = ok?4 : frac>=0.7?3 : frac>=0.35?2 : 1;
  const host=$("#spotwrap");
  o.lines.forEach((l,i)=>{
    const el=host.querySelector('.spotline[data-i="'+i+'"]'); if(!el) return;
    el.classList.remove("pick");
    if(l.bad&&picked[i]) el.classList.add("hit");
    else if(l.bad) el.classList.add("miss");
    else if(picked[i]) el.classList.add("fp");
    if(l.why){ const t=el.querySelector(".lt");
      if(t) t.insertAdjacentHTML("beforeend", `<span class="lw"><b>${l.bad?(picked[i]?"You found it. ":"Missed. "):"This one is fine. "}</b>${l.why}</span>`); }
  });
  const cb=$("#check"); if(cb) cb.remove();
  const ss=$("#spotsel"); if(ss) ss.remove();
  /* The exam recap and the mistake journal do not have the annotated listing
     in front of them, so the solution has to carry the flawed lines itself. */
  const flaws=o.lines.map((l,i)=>({l,i})).filter(x=>x.l.bad)
    .map(x=>`<div class="spotline ${picked[x.i]?"hit":"miss"}" style="cursor:default">
      <span class="ln">${x.i+1}</span><span class="lt">${o.mono?esc(x.l.t):x.l.t}
      <span class="lw"><b>${picked[x.i]?"You found it. ":"Missed. "}</b>${x.l.why}</span></span></div>`).join("");
  const sol = `<div class="spotwrap${o.mono?" mono":""}" style="margin-top:0">${flaws}</div>`
    + (fp?`<p>You also flagged <b>${fp}</b> line${fp>1?"s":""} that were sound. Flagging everything is not free — on a real review it costs the reviewer's attention and your credibility.</p>`:"")
    + (o.close||"");
  record(cur.p, ok, cur.ms, null, grade, ok?null:{q:o.stem,
    sol:sol, yours:hit+" found, "+fp+" false", correct:nbad+" of "+nbad, unit:""});
  if(!ok) requeue(cur.p);
  showFeedback(ok, `${hit} of ${nbad} found${fp?", "+fp+" false positive"+(fp>1?"s":""):""}`, "",
    sol, null, grade, ok?"ok":frac>=0.35?"mid":"no");
}

/* ---------------- tune it ---------------- */
function wireTune(){
  const box=$("#tunectl"); if(!box) return;
  const o=cur.o;
  box.innerHTML=o.controls.map(c=>{
    const v=cur.vals[c.n];
    return `<div class="labslider">
      <div class="lsl"><span>${c.label}</span><em id="tv-${c.n}">${c.fmt?c.fmt(v):L.f2(v,c.dec===undefined?2:c.dec)}${c.unit||""}</em></div>
      <input type="range" id="tc-${c.n}" min="${c.lo}" max="${c.hi}" step="${c.step}" value="${v}">
      <div class="lsv">${c.note||""}</div></div>`;
  }).join("");
  o.controls.forEach(c=>{
    const el=$("#tc-"+c.n); if(!el) return;
    el.addEventListener("input",()=>{
      cur.vals[c.n]=+el.value;
      const lab=$("#tv-"+c.n);
      if(lab) lab.textContent=(c.fmt?c.fmt(cur.vals[c.n]):L.f2(cur.vals[c.n],c.dec===undefined?2:c.dec))+(c.unit||"");
      drawTune();
    });
  });
  const cb=$("#check"); if(cb) cb.onclick=submitTune;
  const hb=$("#hintb"); if(hb) hb.onclick=showHint;
  drawTune();
}
function drawTune(){
  const host=$("#tunelive"); if(!host||!cur.o) return;
  const o=cur.o, v=cur.vals;
  let h="";
  const rd=o.readout?o.readout(v):null;
  if(rd&&rd.length){
    h+=`<div class="tuneread">`+rd.map(r=>`<div><b style="${r.tone==="pos"?"color:var(--pos)":r.tone==="neg"?"color:var(--neg)":r.tone==="warn"?"color:var(--warn)":""}">${r.v}</b><span>${r.l}</span></div>`).join("")+`</div>`;
  }
  if(o.chart){
    const c=o.chart(v);
    if(c&&c.vals&&c.vals.length>1){
      const w=640,ht=c.h||120;
      /* Many of these surfaces have one enormous value at an extreme setting —
         infinite cost at a one-day rebalance, ruin at maximum leverage — which
         flattens the whole interesting region into a line. Clip to a trimmed
         range unless the item says otherwise, and clamp the path to it. */
      const srt=c.vals.slice().sort((a,b)=>a-b);
      const qt=f=>srt[Math.min(srt.length-1,Math.max(0,Math.round(f*(srt.length-1))))];
      /* Tukey fence: one enormous value at an extreme setting — infinite cost
         at a one-day rebalance, ruin at maximum leverage — otherwise squashes
         the whole interesting region into a flat line. */
      const q1=qt(0.25), q3=qt(0.75), iqr=Math.max(q3-q1, 1e-12);
      const lo=c.lo!==undefined?c.lo:Math.max(srt[0], q1-1.8*iqr);
      const hi=c.hi!==undefined?c.hi:Math.min(srt[srt.length-1], q3+1.8*iqr);
      const pad=(hi-lo)*0.08||1, y0=lo-pad, y1=hi+pad;
      const px=i=>6+i/Math.max(c.vals.length-1,1)*(w-12);
      const py=x=>ht-8-(Math.max(y0,Math.min(y1,x))-y0)/(y1-y0)*(ht-16);
      const d=c.vals.map((x,i)=>(i?"L":"M")+px(i).toFixed(1)+" "+py(x).toFixed(1)).join(" ");
      const base=c.base!==undefined?`<line x1="6" y1="${py(c.base).toFixed(1)}" x2="${w-6}" y2="${py(c.base).toFixed(1)}" stroke="var(--rule-strong)" stroke-dasharray="3 3"/>`:"";
      h+=`<svg class="chart" viewBox="0 0 ${w} ${ht}" preserveAspectRatio="none" style="height:${ht}px">${base}
        <path d="${d} L ${px(c.vals.length-1).toFixed(1)} ${ht-8} L 6 ${ht-8} Z" fill="${c.color||"var(--accent)"}" opacity=".13"/>
        <path d="${d}" fill="none" stroke="${c.color||"var(--accent)"}" stroke-width="1.8" stroke-linejoin="round"/></svg>`;
      if(c.caption) h+=`<div class="labnote">${c.caption}</div>`;
    }
  }
  host.innerHTML=h;
}
function submitTune(){
  if(phase!=="answer") return;
  const o=cur.o;
  stopClock(); cur.ms=Date.now()-t0;
  const yours=o.score(cur.vals);
  const best=o.score(o.best);
  const worst=o.worst!==undefined?o.worst:null;
  /* graded on how much of the achievable objective you captured, not on
     hitting the exact control value — the surface is usually flat near
     the optimum and that flatness is itself the lesson */
  let frac;
  if(worst!==null && best!==worst) frac=(yours-worst)/(best-worst);
  else frac = best!==0 ? 1-Math.abs(yours-best)/Math.abs(best) : (Math.abs(yours)<1e-9?1:0);
  frac=Math.max(0,Math.min(1,frac));
  const ok=frac>=(o.pass!==undefined?o.pass:0.9);
  const grade = frac>=0.97?4 : frac>=(o.pass!==undefined?o.pass:0.9)?3 : frac>=0.6?2 : 1;
  const ctlLine=o.controls.map(c=>{
    const yv=cur.vals[c.n], bv=o.best[c.n];
    const fm=x=>(c.fmt?c.fmt(x):L.f2(x,c.dec===undefined?2:c.dec))+(c.unit||"");
    return `<tr><td>${c.label}</td><td class="r">${fm(yv)}</td><td class="r">${fm(bv)}</td></tr>`;
  }).join("");
  const sol=`<table class="st" style="margin:2px 0 12px"><thead><tr><th>control</th><th style="text-align:right">you</th><th style="text-align:right">best</th></tr></thead>
    <tbody>${ctlLine}</tbody></table>
    <p>You captured <b>${L.f2(frac*100,0)}%</b> of what was available. ${o.sol||""}</p>
    ${o.close?`<p>${o.close}</p>`:""}`;
  record(cur.p, ok, cur.ms, null, grade, ok?null:{q:o.goal, sol:sol,
    yours:L.f2(frac*100,0)+"% captured", correct:"100%", unit:""});
  if(!ok) requeue(cur.p);
  showFeedback(ok, `${L.f2(frac*100,0)}% of the available objective`, "", sol, null, grade,
    ok?"ok":frac>=0.6?"mid":"no");
}

function showHint(){
  const o=cur.o; if(!o||!o.hint) return;
  const h=$("#fb"); if(!h||h.querySelector(".hintbox")) return;
  h.innerHTML=`<div class="hintbox fadein"><b>Hint.</b> ${o.hint}</div>`;
  cur.usedHint=true;
  const inp=$("#ans"); if(inp) inp.focus();
}

/* ---- numeric / estimate ---- */
function submitNum(){
  if(phase!=="answer") return;
  const inp=$("#ans"); if(!inp) return;
  const raw=(inp.value||"").trim();
  if(!raw){ inp.focus(); return; }
  const v=evalExpr(raw);
  if(!isFinite(v)){ inp.classList.add("bad"); inp.focus(); return; }
  cur.v=v; cur.ms=Date.now()-t0; stopClock();
  inp.disabled=true; const c=$("#check"); if(c) c.disabled=true;
  const hb=$("#hintb"); if(hb) hb.disabled=true;
  askConfidence(conf=>markNum(conf));
}
/* A question that asks for "2 dp" must accept an answer correctly rounded to
   2 dp, whatever the item's own tolerance says. Relative tolerances break this
   silently whenever the answer is small — and the failure is invisible to the
   learner, who is right and is told otherwise. So the stated precision acts as
   a floor on the tolerance everywhere. */
function statedPrecisionFloor(q){
  const t=String(q||"");
  const m=/to (\d)\s?dp/i.exec(t);
  if(m) return 0.5*Math.pow(10,-(+m[1]));
  /* "to the nearest cent" and friends */
  if(/to the (nearest )?cent\b/i.test(t)) return 0.005;
  /* "to the nearest whole / integer / second / day / month / contract …" —
     an answer rounded as instructed must be accepted. */
  if(/to (the )?(nearest|whole)\b/i.test(t)) return 0.5;
  return 0;
}
function effectiveTol(o){
  const base = o.rel ? Math.abs(o.a)*o.tol : o.tol;
  if(o.int) return base;
  return Math.max(base, statedPrecisionFloor(o.q));
}
function markNum(conf){
  const p=cur.p, o=cur.o, v=cur.v;
  let ok, extra, grade;
  if(p.kind==="estimate"){
    const lr=Math.abs(Math.log10(Math.max(v,1e-12)/o.a));
    ok = lr<=1;
    const band = lr<=0.3?"within 2×" : lr<=0.5?"within 3×" : lr<=1?"within 10×" : "more than 10× out";
    grade = lr<=0.3?4 : lr<=0.5?3 : lr<=1?2 : 1;
    extra=`<div>You said ${withUnit(v,o.unit)} &middot; actual ${withUnit(o.a,o.unit)}
      &middot; <b>${band}</b> (${v>o.a?"×":"÷"}${fmtNum(Math.max(v,o.a)/Math.min(v,o.a))})</div>`;
  } else {
    const tol = effectiveTol(o);
    ok = Math.abs(v-o.a) <= tol + 1e-9;
    grade = gradeOf(ok, cur.ms, targetSec(p));
    if(ok && cur.usedHint && grade>3) grade=3;
    extra=`<div>You said ${withUnit(v,o.unit)} &middot; correct ${withUnit(o.a,o.unit)}${tol>0?` <span style="opacity:.65">(±${fmtNum(tol)})</span>`:""}${!ok?` &middot; off by <b>${fmtNum(Math.abs(v-o.a))}</b>${Math.abs(o.a)>1e-9?` (${fmtNum(Math.abs(v-o.a)/Math.abs(o.a)*100)}%)`:""}`:""}</div>`;
  }
  record(p, ok, cur.ms, conf, grade, ok?null:{q:o.q, sol:o.sol, yours:fmtNum(v), correct:fmtNum(o.a), unit:o.unit||""});
  if(!ok) requeue(p);
  showFeedback(ok, ok?(p.kind==="estimate"?"Good estimate":"Correct"):(p.kind==="estimate"?"Too far out":"Not quite"), extra, o.sol, conf, grade);
}

/* ---- multiple choice ---- */
function chooseOpt(i){
  if(phase!=="answer") return;
  cur.choice=i; cur.ms=Date.now()-t0; stopClock();
  $$("#opts .opt").forEach((b,bi)=>{ b.disabled=true; if(bi===i) b.classList.add("chosen"); });
  askConfidence(conf=>markOpt(conf));
}
function markOpt(conf){
  const p=cur.p, i=cur.choice, ok=cur.opts[i].ok;
  $$("#opts .opt").forEach((b,bi)=>{
    if(cur.opts[bi].ok) b.classList.add("right");
    else if(bi===i) b.classList.add("wrong");
  });
  const grade=gradeOf(ok, cur.ms, targetSec(p));
  record(p, ok, cur.ms, conf, grade, ok?null:{q:p.j.q, sol:p.j.sol, yours:cur.opts[i].t,
    correct:cur.opts.find(o=>o.ok).t, unit:""});
  if(!ok) requeue(p);
  showFeedback(ok, ok?"Correct":"Not quite",
    MODE.exam?`<div>You chose &ldquo;${esc(cur.opts[i].t)}&rdquo;${ok?"":` &middot; the answer was &ldquo;${esc(cur.opts.find(o=>o.ok).t)}&rdquo;`}</div>`:"",
    p.j.sol, conf, grade);
}

/* ---- recall ---- */
function revealCard(){
  if(phase!=="answer") return;
  phase="selfgrade"; cur.ms=Date.now()-t0; stopClock();
  const p=cur.p;
  const box=$("#commit"); const said=box? (box.value||"").trim() : "";
  if(box) box.disabled=true;
  $("#fb").innerHTML=`${said?`<div class="fb plain fadein" style="margin-bottom:-6px"><div class="hd">What you said</div>
    <div style="font-family:var(--serif);font-size:15.5px;color:var(--ink);white-space:pre-wrap">${esc(said)}</div></div>`:""}
    <div class="fb plain fadein"><div class="hd">The answer</div>
    <div class="sol" style="border-top:none;padding-top:0;margin-top:0">${p.c.a}</div>
    <div class="selfrow">
      <button class="btn" id="g1">Missed it <kbd>1</kbd></button>
      <button class="btn" id="g2">Hard <kbd>2</kbd></button>
      <button class="btn on" id="g3">Got it <kbd>3</kbd></button>
      <button class="btn" id="g4">Easy <kbd>4</kbd></button>
    </div><div class="hint" style="margin-top:10px">Grade honestly. Recognising the answer is not producing it — if you could not have said it out loud, that is "missed it".</div></div>`;
  [1,2,3,4].forEach(g=>{ const b=$("#g"+g); if(b) b.onclick=()=>gradeCard(g); });
  const b3=$("#g3"); if(b3) b3.focus();
}
function gradeCard(g){
  if(phase!=="selfgrade") return;
  const p=cur.p, ok=g>=3;
  record(p, ok, cur.ms, null, g, null);
  if(!ok) requeue(p);
  advance();
}

/* ---- derivations ---- */
function renderSteps(){
  const o=cur.o, host=$("#steps");
  let h="";
  o.steps.forEach((st,i)=>{
    if(i<cur.step){
      const r=cur.results[i];
      h+=`<div class="step ${r.ok?"done":"miss"}"><div class="sq">${st.q}</div>
        <div class="sa">you <span class="${r.ok?"yes":"no"}">${esc(r.yours)}</span> &middot; correct ${withUnit(st.a,st.unit)}</div>
        <div class="stepsol">${st.sol}</div></div>`;
    } else if(i===cur.step){
      h+=`<div class="step active"><div class="sq">${st.q}</div>
        <div class="ansrow" style="margin-top:4px"><input class="num" id="ans" inputmode="text" autocomplete="off" spellcheck="false" placeholder="answer">
        <span class="unit">${esc(st.unit||"")}</span>
        <button class="btn on" id="check">Check&nbsp; <kbd>&crarr;</kbd></button>
        ${st.hint&&!MODE.exam?'<button class="btn ghost sm" id="hintb">Hint <kbd>h</kbd></button>':""}</div>
        <div class="evalhint" id="ev"></div></div>`;
    } else {
      h+=`<div class="step pending"><div class="sq">Step ${i+1}</div></div>`;
    }
  });
  host.innerHTML=h;
  const inp=$("#ans");
  if(inp){ inp.focus(); inp.addEventListener("input",showEval); }
  const cb=$("#commit");
  if(cb){ cb.focus(); cb.addEventListener("keydown", e=>{
    if(e.key==="Enter" && !e.shiftKey){ e.preventDefault(); revealCard(); return; }
    /* The card says space skips the box, and while the box has focus the global
       key handler never sees the key. On an empty box a space is not meaningful
       input, so honour the documented shortcut here. */
    if(e.key===" " && !cb.value){ e.preventDefault(); revealCard(); } }); }
  if($("#check")) $("#check").onclick=submitStep;
  if($("#hintb")) $("#hintb").onclick=()=>{
    const st=cur.o.steps[cur.step];
    const s=$(".step.active"); if(!s||s.querySelector(".hintbox")) return;
    s.insertAdjacentHTML("beforeend",`<div class="hintbox fadein"><b>Hint.</b> ${st.hint}</div>`);
    cur.usedHint=true; const a=$("#ans"); if(a) a.focus();
  };
  const active=$(".step.active"); if(active) active.scrollIntoView({block:"nearest",behavior:"smooth"});
}
function submitStep(){
  if(phase!=="answer") return;
  const inp=$("#ans"); if(!inp) return;
  const raw=(inp.value||"").trim(); if(!raw){ inp.focus(); return; }
  const v=evalExpr(raw);
  if(!isFinite(v)){ inp.classList.add("bad"); inp.focus(); return; }
  const st=cur.o.steps[cur.step];
  const tol = effectiveTol(st);
  const ok = Math.abs(v-st.a) <= tol + 1e-9;
  cur.results.push({ok, yours:fmtNum(v)});
  cur.step++;
  if(cur.step<cur.o.steps.length){ renderSteps(); return; }
  /* whole derivation finished */
  stopClock();
  const nOk=cur.results.filter(r=>r.ok).length, n=cur.results.length;
  cur.ms=Date.now()-t0;
  renderSteps();
  askConfidence(conf=>finishDerive(conf,nOk,n));
}
function finishDerive(conf, nOk, n){
  const p=cur.p, frac=nOk/n;
  const ok=frac>=0.8;
  const grade = frac>=0.99?4 : frac>=0.8?3 : frac>=0.5?2 : 1;
  record(p, ok, cur.ms, conf, grade, ok?null:{q:cur.o.stem,
    sol:cur.o.close, yours:nOk+" of "+n+" steps", correct:"all "+n+" steps", unit:""});
  if(!ok) requeue(p);
  const cls = frac>=0.8?"ok" : frac>=0.5?"mid":"no";
  const title = frac>=0.99?"All steps correct" : `${nOk} of ${n} steps correct`;
  showFeedback(ok, title, "", cur.o.close, conf, grade, cls);
}

/* ---- desk ---- */
function renderRound(){
  const o=cur.o, host=$("#rounds");
  let h=`<div class="tally">${o.rounds.map((_,i)=>{
    if(i>=cur.round) return `<i></i>`;
    const s=cur.scores[i];
    return `<i class="${s>=2?"s2":s===1?"s1":s===0?"s0":"sneg"}"></i>`;
  }).join("")}</div>`;
  o.rounds.forEach((rd,i)=>{
    if(i>cur.round) return;
    if(i<cur.round){
      const chosen=cur.chosenIdx[i];
      h+=`<div class="round"><div class="rq">${rd.q}</div>`;
      rd.opts.forEach((op,oi)=>{
        if(oi!==chosen && op.score<2) return;
        const cls=op.score>=2?"s2":op.score===1?"s1":op.score===0?"s0":"sneg";
        h+=`<div class="dopt ${cls}" style="cursor:default"><kbd>${oi===chosen?"you":"best"}</kbd><span>${op.t}</span></div>
          <div class="dwhy">${op.why}</div>`;
      });
      h+=`</div>`;
    } else {
      h+=`<div class="round"><div class="rq">${rd.q}</div><div id="dopts">`+
        rd.opts.map((op,oi)=>`<button class="dopt" data-i="${oi}"><kbd>${oi+1}</kbd><span>${op.t}</span></button>`).join("")+
        `</div></div>`;
    }
  });
  host.innerHTML=h;
  $$("#dopts .dopt").forEach(b=>b.onclick=()=>chooseDesk(+b.dataset.i));
  const last=$("#dopts"); if(last) last.scrollIntoView({block:"nearest",behavior:"smooth"});
}
function chooseDesk(i){
  if(phase!=="answer") return;
  const rd=cur.o.rounds[cur.round];
  cur.chosenIdx=cur.chosenIdx||[];
  cur.chosenIdx.push(i);
  cur.scores.push(rd.opts[i].score);
  cur.round++;
  if(cur.round<cur.o.rounds.length){ renderRound(); return; }
  stopClock(); cur.ms=Date.now()-t0;
  renderRound();
  const max=cur.o.rounds.length*2;
  const got=cur.scores.reduce((a,b)=>a+b,0);
  const frac=Math.max(0,got)/max;
  const ok=frac>=0.75;
  const grade = frac>=0.95?4 : frac>=0.75?3 : frac>=0.45?2 : 1;
  record(cur.p, ok, cur.ms, null, grade, ok?null:{q:cur.o.brief, sol:cur.o.close,
    yours:got+" of "+max, correct:max+" of "+max, unit:""});
  if(!ok) requeue(cur.p);
  sessionScore+=got;
  showFeedback(ok, `${got} of ${max} on the decisions`, "", cur.o.close, null, grade,
    frac>=0.75?"ok":frac>=0.45?"mid":"no");
}

/* ---- shared feedback + advance ---- */
function showFeedback(ok, title, extra, sol, conf, grade, forceCls){
  const p=cur.p;
  if(MODE.exam){
    /* under exam conditions nothing is shown until the end — feedback during
       the test is what makes a practice test feel like studying and stops it
       measuring anything. */
    /* Keep the question with the answer: a recap that shows only the working
       is unreadable for the kinds whose question carries the content. */
    const o=cur.o||{};
    const stem = p.kind==="judge" ? (p.j&&p.j.q)
      : p.kind==="recall" ? (p.c&&p.c.q)
      : (o.q || o.stem || o.brief || o.goal || (o.ask?("Give an expression for <b>"+o.ask+"</b>."):"") || "");
    examLog.push({name:p.name, dom:p.dom, kind:p.kind, ok, title, extra:extra||"", sol, stem,
                  conf, ms:cur.ms||0, vol:p.vol});
    advance(); return;
  }
  phase="feedback";
  const cls = forceCls || (ok?"ok":"no");
  const gl=["","again","hard","good","easy"][grade]||"";
  const k=sk(p.key);
  const nextIn = k.due? fmtDays(Math.max(0,(k.due-Date.now())/DAY)) : "soon";
  const meta=`<span class="meta">${fmtDur(cur.ms||0)} &middot; target ${targetSec(p)}s &middot; back in ${nextIn}</span>`;
  const host=$("#fb");
  host.innerHTML=`<div class="fb ${cls} fadein"><div class="hd">${esc(title)} ${confBadge(conf,ok)}
      <span class="badge">${gl}</span>${meta}</div>
    ${extra||""}
    <div class="sol">${sol}</div>
    ${xrefLink(p)}
    <div class="selfrow"><button class="btn on" id="next">Next&nbsp; <kbd>&crarr;</kbd></button>
      ${!ok?`<button class="btn ghost sm" id="undo" title="Restore the schedule and ask it again">I mistyped <kbd>u</kbd></button>`:""}
      <button class="btn ghost sm" id="susp" title="Stop showing this item">Suspend <kbd>x</kbd></button></div></div>`;
  const nb=$("#next"); if(nb){ nb.onclick=advance; nb.focus(); }
  const sb=$("#susp"); if(sb) sb.onclick=()=>{ sk(p.key).susp=1; save(); advance(); };
  const ub=$("#undo"); if(ub) ub.onclick=()=>{ if(undoLast()) render(); };
  host.scrollIntoView({block:"nearest", behavior:"smooth"});
  if(S.settings.autoAdv && ok) setTimeout(()=>{ if(phase==="feedback") advance(); }, 1400);
}
function requeue(p){
  /* a failed item comes back once more before the set ends — the second
     retrieval, after a real gap, is what fixes it. Once only, or a bad
     session becomes unbounded. Never under exam conditions: a test that
     re-asks what you missed is not a test. */
  if(MODE.exam) return;
  if(relearned[p.key]) return;
  /* and cap the tail: a session where everything goes wrong should end and be
     rescheduled, not grow without limit */
  if(relearn.length >= Math.max(4, Math.ceil(MODE.len*0.4))) return;
  relearned[p.key]=1; relearn.push(p);
}
function advance(){ idx++; render(); }

/* ============================================================
   10. SESSION END
   ============================================================ */
function renderExamDone(){
  stopClock(); phase="done";
  const mins=(Date.now()-startedAt)/60000;
  const n=examLog.length, ok=examLog.filter(e=>e.ok).length;
  const pct=n?Math.round(ok/n*100):0;
  S.sessions.push({t:Date.now(), n:sessionN, ok:sessionOk, ms:Date.now()-startedAt, exam:1});
  saveNow();
  const withConf=examLog.filter(e=>e.conf!=null);
  const brier=withConf.length? withConf.reduce((s,e)=>s+Math.pow(e.conf-(e.ok?1:0),2),0)/withConf.length : null;
  const byDom={};
  examLog.forEach(e=>{ const d=byDom[e.dom]||(byDom[e.dom]={n:0,ok:0}); d.n++; if(e.ok)d.ok++; });
  const worst=Object.entries(byDom).filter(([,v])=>v.n>=2).sort((a,b)=>a[1].ok/a[1].n-b[1].ok/b[1].n).slice(0,3);
  $("#stage").innerHTML=`<div class="card-wrap fadein">
    <div class="done" style="padding-bottom:6px"><h2>${ok} of ${n} &mdash; ${pct}%</h2>
      <div class="big" style="justify-content:center">
        <div><b>${pct}%</b><span>score</span></div>
        <div><b>${mins.toFixed(1)}</b><span>minutes</span></div>
        <div><b>${(mins*60/Math.max(n,1)).toFixed(0)}s</b><span>per item</span></div>
        ${brier!=null?`<div><b>${brier.toFixed(3)}</b><span>brier</span></div>`:""}
      </div></div>
    <p class="intro">${pct>=85?"A strong result under exam conditions — no hints, no feedback, one pass. That is the closest thing here to how you will be assessed."
      : pct>=65?"Respectable. The gap between practice accuracy and exam accuracy is almost always attention rather than knowledge: under no-feedback conditions there is nothing to correct a misread question."
      : "Well below your practice accuracy, which is the normal and useful finding. Feedback after every item quietly does a lot of work; removing it shows you what you can actually produce unaided."}</p>
    ${worst.length?`<p class="intro" style="font-size:16px">Weakest here: ${worst.map(([d,v])=>`<b>${esc(d)}</b> (${v.ok}/${v.n})</b>`).join(", ").replace(/<\/b><\/b>/g,"</b>")}.</p>`:""}
    <div class="modes"><button class="btn on" id="restart">Another exam&nbsp; <kbd>&crarr;</kbd></button>
      <button class="btn" id="backMix">Back to practice</button>
      <button class="btn" id="toStats">Progress</button></div>
    <h2 class="sec">Every question, with the working</h2>
    <p class="sub">Read the ones you got wrong now, while you still remember what you were thinking.</p>
    ${examLog.map((e,i)=>`<div class="mx" style="margin-bottom:10px;padding:14px 16px">
      <div class="n"><span>${i+1}. ${esc(e.name||e.dom)} <span class="badge ${e.ok?"good":"bad"}">${e.ok?"right":"wrong"}</span></span>
        <em>${esc(e.dom)} &middot; ${fmtDur(e.ms)}${e.conf!=null?" &middot; said "+Math.round(e.conf*100)+"%":""}</em></div>
      ${e.stem?`<div style="margin:8px 0 4px;font-size:14.5px;line-height:1.6;color:var(--ink-2)">${e.stem}</div>`:""}
      ${e.extra?`<div style="font:600 13px var(--mono);color:var(--ink-3);margin:6px 0">${e.extra}</div>`:""}
      <div class="sol" style="border-top:1px solid var(--rule)">${e.sol}</div></div>`).join("")}
  </div>`;
  $("#prog").style.width="100%";
  $("#restart").onclick=()=>start();
  $("#backMix").onclick=()=>{ MODE.exam=false; MODE.mix=MODE.prevMix||S.settings.mix||"balanced";
    MODE.len=25; restoreCnt(); syncChips(); start(); };
  $("#toStats").onclick=()=>showPanel("stats");
  updateBar();
}
function renderDone(){
  if(MODE.exam) return renderExamDone();
  stopClock(); clearInterval(drillT); phase="done";
  if(MODE.onDone){ var _cb=MODE.onDone; MODE.onDone=null; MODE.vols=null;
    try{ _cb({n:sessionN, ok:sessionOk}); }catch(_e){} }
  const mins=(Date.now()-startedAt)/60000;
  const acc=sessionN?Math.round(sessionOk/sessionN*100):0;
  S.sessions.push({t:Date.now(), n:sessionN, ok:sessionOk, ms:Date.now()-startedAt});
  if(S.sessions.length>500) S.sessions=S.sessions.slice(-400);
  saveNow();
  const recent=S.hist.slice(-sessionN).filter(h=>h.conf!=null);
  const brier=recent.length? recent.reduce((s,h)=>s+Math.pow(h.conf-h.ok,2),0)/recent.length : null;
  const overconf=recent.length? (recent.reduce((s,h)=>s+h.conf,0)/recent.length) - (recent.reduce((s,h)=>s+h.ok,0)/recent.length) : null;
  const due=dueCount();
  const msg = acc>=88 ? "Strong. The queue will push you into harder tiers and longer intervals — which is the system working, not a reward being withheld."
    : acc>=62 ? "About right. Somewhere near 85% correct is the target: much higher means the material is too easy to be worth the time, much lower means the queue is ahead of you."
    : "Below 60%. Not a disaster — but open the skill matrix, take the two weakest domains, and read those sections before the next set. Practice cannot install knowledge that was never there.";
  $("#stage").innerHTML=`<div class="card-wrap fadein"><div class="done">
    <h2>${sessionOk} of ${sessionN} correct</h2>
    <div class="big" style="justify-content:center">
      <div><b>${acc}%</b><span>accuracy</span></div>
      <div><b>${mins.toFixed(1)}</b><span>minutes</span></div>
      <div><b>${(sessionN/Math.max(mins,0.01)).toFixed(1)}</b><span>items / min</span></div>
      <div><b>${S.best}</b><span>best streak</span></div>
      ${brier!=null?`<div><b>${brier.toFixed(3)}</b><span>brier</span></div>`:""}
      <div><b>${due}</b><span>still due</span></div>
    </div>
    <p class="intro" style="margin:18px auto 0;text-align:left">${msg}</p>
    ${overconf!=null?`<p class="intro" style="margin:10px auto 0;text-align:left">${
      Math.abs(overconf)<0.05?"Your confidence tracked your accuracy closely this session — calibration is the rarer skill and you have it here."
      : overconf>0?`You were <b>overconfident</b> by ${Math.round(overconf*100)} points on average. Overconfidence is what turns a position that should be small into one that is not.`
      : `You were <b>underconfident</b> by ${Math.round(-overconf*100)} points. Less costly than the reverse, and it still means you are leaving conviction — and size — on the table.`}</p>`:""}
    <div class="modes" style="justify-content:center">
      <button class="btn on" id="restart">Another set&nbsp; <kbd>&crarr;</kbd></button>
      ${due>0?`<button class="btn" id="dodue">Clear the ${due} due</button>`:""}
      <button class="btn" id="toStats">Progress</button></div>
  </div></div>`;
  $("#prog").style.width="100%";
  $("#restart").onclick=()=>start();
  const dd=$("#dodue"); if(dd) dd.onclick=()=>{ MODE.dueOnly=true; MODE.len=Math.min(due,80); start(); };
  $("#toStats").onclick=()=>showPanel("stats");
  updateBar();
}

/* ============================================================
   11. START
   ============================================================ */
function start(opts){
  if(!(opts&&opts.vols)){ MODE.vols=null; MODE.onDone=null; }
  Object.assign(MODE, opts||{});
  hidePanel();
  clearInterval(drillT); queue=buildQueue(); idx=0; relearn=[]; relearned=Object.create(null);
  sessionOk=0; sessionN=0; sessionScore=0; examLog=[];
  startedAt=Date.now();
  if(!queue.length){
    $("#stage").innerHTML=`<div class="card-wrap"><h2 class="sec">Nothing matches</h2>
      <p class="sub">${MODE.dueOnly?"Nothing is due yet — which is the system telling you to stop, not to push. Turn off <b>due only</b> to study ahead.":"No items match that filter. Widen the domain or the mix."}</p>
      <div class="modes"><button class="btn on" id="clr">Clear filters</button></div></div>`;
    $("#clr").onclick=()=>{ MODE.dom=null; MODE.dueOnly=false; MODE.weak=false; MODE.speed=0; MODE.kinds=null;
      const s=$("#dom"); if(s) s.value=""; syncChips(); start(); };
    return;
  }
  render();
}

function startSingle(key){
  const p=BYKEY[key]; if(!p) return;
  hidePanel(); clearInterval(drillT);
  MODE.exam=false; MODE.speed=0;
  queue=[p]; idx=0; relearn=[]; relearned=Object.create(null);
  sessionOk=0; sessionN=0; sessionScore=0; examLog=[]; startedAt=Date.now();
  restoreCnt(); syncChips(); render();
}

/* ============================================================
   12. ANALYTICS
   ============================================================ */
function domStats(){
  const by={};
  POOL.forEach(p=>{
    const d=by[p.dom]||(by[p.dom]={n:0,seen:0,att:0,ok:0,mature:0,ms:[],dom:p.dom});
    d.n++;
    const k=S.sk[p.key];
    if(k&&k.seen){ d.seen++; d.att+=k.seen; d.ok+=k.ok; if(k.s>=21) d.mature++; }
  });
  S.hist.forEach(h=>{ if(by[h.dom]) by[h.dom].ms.push(h.ms); });
  return Object.values(by);
}
function median(a){ if(!a.length) return 0; const b=a.slice().sort((x,y)=>x-y); return b[Math.floor(b.length/2)]; }

function svgLine(pts, w, h, opts){
  opts=opts||{};
  if(!pts.length) return "";
  const xs=pts.map(p=>p[0]), ys=pts.map(p=>p[1]);
  const x0=opts.x0!==undefined?opts.x0:Math.min(...xs), x1=opts.x1!==undefined?opts.x1:Math.max(...xs);
  const y0=opts.y0!==undefined?opts.y0:0, y1=opts.y1!==undefined?opts.y1:Math.max(...ys,1);
  const px=v=>34+(v-x0)/Math.max(x1-x0,1e-9)*(w-46);
  const py=v=>h-24-(v-y0)/Math.max(y1-y0,1e-9)*(h-38);
  const d=pts.map((p,i)=>(i?"L":"M")+px(p[0]).toFixed(1)+" "+py(p[1]).toFixed(1)).join(" ");
  let g="";
  for(let i=0;i<=4;i++){ const v=y0+(y1-y0)*i/4;
    g+=`<line class="gridln" x1="34" y1="${py(v).toFixed(1)}" x2="${w-12}" y2="${py(v).toFixed(1)}"/>
        <text x="28" y="${(py(v)+3).toFixed(1)}" text-anchor="end">${opts.fmtY?opts.fmtY(v):Math.round(v)}</text>`; }
  const dots=pts.map(p=>`<circle cx="${px(p[0]).toFixed(1)}" cy="${py(p[1]).toFixed(1)}" r="3" fill="${opts.color||"var(--accent)"}"/>`).join("");
  const labels=(opts.xlabels||[]).map(l=>`<text x="${px(l[0]).toFixed(1)}" y="${h-8}" text-anchor="middle">${esc(l[1])}</text>`).join("");
  const ref = opts.ref!==undefined ? `<line class="gridln" style="stroke:var(--info);stroke-dasharray:4 3" x1="34" y1="${py(opts.ref).toFixed(1)}" x2="${w-12}" y2="${py(opts.ref).toFixed(1)}"/>`:"";
  return `<svg class="chart" viewBox="0 0 ${w} ${h}" role="img">${g}${ref}
    <path d="${d}" fill="none" stroke="${opts.color||"var(--accent)"}" stroke-width="2" stroke-linejoin="round"/>
    ${dots}${labels}</svg>`;
}

function retentionData(){
  const buckets=[[0,1],[1,3],[3,7],[7,21],[21,60],[60,1e9]];
  const lbl=["<1d","1–3d","3–7d","1–3w","3w–2m","2m+"];
  const out=buckets.map(()=>({n:0,ok:0}));
  S.hist.forEach(h=>{ if(h.el==null) return;
    for(let i=0;i<buckets.length;i++){ if(h.el>=buckets[i][0]&&h.el<buckets[i][1]){ out[i].n++; out[i].ok+=h.ok; break; } } });
  return {out, lbl};
}
function calibrationData(){
  const bins=[[0.5,0.575],[0.575,0.725],[0.725,0.85],[0.85,0.94],[0.94,1.01]];
  const lbl=["50%","65%","80%","90%","98%"];
  const out=bins.map(()=>({n:0,ok:0,sum:0}));
  S.hist.forEach(h=>{ if(h.conf==null) return;
    for(let i=0;i<bins.length;i++){ if(h.conf>=bins[i][0]&&h.conf<bins[i][1]){ out[i].n++; out[i].ok+=h.ok; out[i].sum+=h.conf; break; } } });
  const withConf=S.hist.filter(h=>h.conf!=null);
  const brier=withConf.length? withConf.reduce((s,h)=>s+Math.pow(h.conf-h.ok,2),0)/withConf.length : null;
  return {out, lbl, brier, n:withConf.length};
}
function forecast(){
  const now=Date.now(), out=new Array(15).fill(0);
  POOL.forEach(p=>{ const k=S.sk[p.key]; if(!k||!k.reps||k.susp) return;
    const d=Math.floor((k.due-now)/DAY);
    if(d<0) out[0]++; else if(d<15) out[d]++; });
  return out;
}

let panel=null;
function showPanel(which){
  panel=which;
  $("#stage").style.display="none"; $("#panel").style.display="block";
  $$("[data-panel]").forEach(b=>{ const on=b.dataset.panel===which;
    b.classList.toggle("on", on); b.setAttribute("aria-expanded", on?"true":"false"); });
  if(which==="stats") renderStats();
  else if(which==="journal") renderJournal();
  else if(which==="bank") renderBank();
  else if(which==="settings") renderSettings();
  window.scrollTo({top:0,behavior:"smooth"});
}
function hidePanel(){
  panel=null;
  $("#stage").style.display="block"; $("#panel").style.display="none";
  $$("[data-panel]").forEach(b=>{ b.classList.remove("on"); b.setAttribute("aria-expanded","false"); });
}

function renderStats(){
  const rows=domStats().sort((a,b)=>{
    const ra=a.att?a.ok/a.att:2, rb=b.att?b.ok/b.att:2; return ra-rb; });
  const tot=S.hist.length, totOk=S.hist.reduce((s,h)=>s+h.ok,0);
  const med=median(S.hist.slice(-300).map(h=>h.ms))/1000;
  const held=Object.values(S.sk).filter(k=>k.s>=21&&!k.susp).length;
  const leeches=POOL.filter(p=>{const k=S.sk[p.key]; return k&&isLeech(k)&&!k.susp;});
  const susp=POOL.filter(p=>{const k=S.sk[p.key]; return k&&k.susp;});
  const ret=retentionData(), cal=calibrationData(), fc=forecast();
  const days=Math.max(1,(Date.now()-S.created)/DAY);

  /* speed trend over sessions */
  const spd=S.sessions.slice(-30).map((s,i)=>[i, s.n? (s.ms/s.n/1000) : 0]).filter(p=>p[1]>0);
  /* accuracy trend, 50-item rolling */
  const win=50, accPts=[];
  for(let i=win;i<=S.hist.length;i+=Math.max(1,Math.floor(S.hist.length/40))){
    const sl=S.hist.slice(i-win,i);
    accPts.push([i, sl.reduce((s,h)=>s+h.ok,0)/win*100]);
  }

  $("#panel").innerHTML=`
  <h2 class="sec">Where you actually are</h2>
  <p class="sub">Ordered worst first. A domain is <b>held</b> only once its items have a memory stability above three weeks — several correct answers spread over real time, not one lucky guess.</p>
  <div class="big">
    <div><b>${tot.toLocaleString("en-US")}</b><span>answered</span></div>
    <div><b>${tot?Math.round(totOk/tot*100):0}%</b><span>lifetime</span></div>
    <div><b>${med.toFixed(1)}s</b><span>median time</span></div>
    <div><b>${held}</b><span>items held</span></div>
    <div><b>${POOL.length.toLocaleString("en-US")}</b><span>in the bank</span></div>
    <div><b>${Math.round(tot/days)}</b><span>per day</span></div>
  </div>
  <div class="grid">${rows.map(v=>{
    const acc=v.att? v.ok/v.att : 0, cov=v.mature/v.n;
    const cls=acc<0.6?"low":acc<0.82?"mid":"";
    const ab=S.ability[v.dom];
    return `<div class="mx click" data-dom="${esc(v.dom)}" title="Practise ${esc(v.dom)}">
      <div class="n"><span>${esc(v.dom)}</span>${ab!==undefined?`<em>${["core","stretch","hard"][ab<0.45?0:ab<0.72?1:2]}</em>`:""}</div>
      <div class="s">${v.att?Math.round(acc*100)+"% right &middot; ":""}${v.mature}/${v.n} held${v.ms.length?" &middot; "+(median(v.ms)/1000).toFixed(1)+"s":""}</div>
      <div class="t"><i class="${cls}" style="width:${(cov*100).toFixed(0)}%"></i></div></div>`;}).join("")}</div>

  <h2 class="sec">Which kinds you are weak at</h2>
  <p class="sub">Accuracy by <em>mode of question</em> rather than by subject. This is often the more actionable
  split: someone who computes well and judges badly has a different problem from someone who judges well and
  cannot produce a formula, and the domain view cannot tell them apart. Click one to practise only that kind.</p>
  <div class="grid">${(function(){
    const by={};
    S.hist.forEach(h=>{ const k=h.kind||"calc"; (by[k]=by[k]||{n:0,ok:0,ms:[]}); by[k].n++; by[k].ok+=h.ok;
      if(h.ms) by[k].ms.push(h.ms); });
    const ks=Object.keys(by).sort((a,b)=>(by[a].ok/by[a].n)-(by[b].ok/by[b].n));
    if(!ks.length) return `<p class="sub">Nothing answered yet.</p>`;
    return ks.map(k=>{
      const v=by[k], acc=v.ok/v.n;
      const total=POOL.filter(p2=>p2.kind===k).length;
      const cls=acc<0.6?"low":acc<0.82?"mid":"";
      return `<div class="mx click" data-kind="${k}" title="Practise ${esc(KINDNAME[k]||k)} only">
        <div class="n"><span>${esc(KINDNAME[k]||k)}</span><em>${v.n} answered</em></div>
        <div class="s">${Math.round(acc*100)}% right${v.ms.length?" &middot; "+(median(v.ms)/1000).toFixed(1)+"s":""} &middot; ${total} in the bank</div>
        <div class="t"><i class="${cls}" style="width:${(acc*100).toFixed(0)}%"></i></div></div>`;
    }).join("");
  })()}</div>

  <h2 class="sec">Retention against delay</h2>
  <p class="sub">Accuracy grouped by how long it had been since you last saw the item. A healthy curve sits near 85–90% and sags only at the longest delays. If the near bars are low, the material is too hard; if the far bars are high, the intervals are too short and you are wasting reviews.</p>
  ${ret.out.some(b=>b.n)?
    svgLine(ret.out.map((b,i)=>[i, b.n?b.ok/b.n*100:0]), 620, 170,
      {y0:0,y1:100,x0:0,x1:ret.out.length-1,ref:85,fmtY:v=>Math.round(v)+"%",
       xlabels:ret.lbl.map((l,i)=>[i,l+" ("+ret.out[i].n+")"])})
    : `<p class="empty">Not enough review history yet — this fills in once items start coming back after a day or more.</p>`}

  <h2 class="sec">Calibration</h2>
  <p class="sub">Your stated confidence against how often you were right. Points on the dashed line are perfectly calibrated; above it means underconfident, below means overconfident. Overconfidence is the expensive direction — it is what turns a position that should be small into one that is not.</p>
  ${cal.n>10?`
    ${svgLine(cal.out.map((b,i)=>[i, b.n?b.ok/b.n*100:0]).filter((p,i)=>cal.out[i].n>0), 620, 180,
      {y0:0,y1:100,x0:0,x1:cal.out.length-1,fmtY:v=>Math.round(v)+"%",color:"var(--you)",
       xlabels:cal.lbl.map((l,i)=>[i,l+" ("+cal.out[i].n+")"])})}
    <div class="legend"><span><i style="background:var(--you)"></i>observed accuracy</span>
      <span>Brier score <b>${cal.brier.toFixed(3)}</b> over ${cal.n} rated answers — lower is better; 0.25 is what you get by saying 50% to everything.</span></div>
    <p class="note">${(()=>{
      const gaps=cal.out.map((b,i)=>b.n>=5?(b.ok/b.n-b.sum/b.n):null).filter(x=>x!==null);
      if(!gaps.length) return "Rate a few more answers for a verdict on direction.";
      const m=gaps.reduce((a,b)=>a+b,0)/gaps.length;
      return Math.abs(m)<0.04 ? "Well calibrated on average. That is genuinely uncommon, and it is the single most transferable skill in this file — a trader who knows what they know sizes correctly without needing to be right more often."
        : m<0 ? `On average you are <b>overconfident by ${Math.round(-m*100)} points</b>. In practice that means the position sized on your 90% conviction should have been sized on ${Math.round((1+m/0.9)*90)}%.`
        : `On average you are <b>underconfident by ${Math.round(m*100)} points</b>. Cheaper than the reverse, and it still costs you: conviction you have earned but do not act on.`;
    })()}</p>`
    : `<p class="empty">Rate your confidence on a few more answers and this chart appears. It is switched on in Settings.</p>`}

  ${accPts.length>2?`<h2 class="sec">Accuracy over time</h2>
  <p class="sub">Rolling accuracy over the last ${win} items. Expect this to stay flat rather than climb — as you improve, the scheduler feeds you harder items and longer intervals to keep you near the edge.</p>
  ${svgLine(accPts, 620, 160, {y0:0,y1:100,ref:85,fmtY:v=>Math.round(v)+"%",color:"var(--pos)"})}`:""}

  ${spd.length>2?`<h2 class="sec">Speed</h2>
  <p class="sub">Median seconds per item, by session. Falling time at constant accuracy is real fluency; falling time with falling accuracy is just rushing.</p>
  ${svgLine(spd, 620, 150, {y0:0,fmtY:v=>v.toFixed(0)+"s",color:"var(--info)"})}`:""}

  <h2 class="sec">What is coming</h2>
  <p class="sub">Items falling due over the next fortnight. A flat bar chart means the schedule is spread; a spike means a day you will want to plan for.</p>
  <div class="fcast">
    ${fc.map((v,i)=>{ const mx=Math.max(...fc,1);
      return `<div class="fc"><div class="fcv">${v||""}</div>
        <div class="fcbar"><i style="height:${v?Math.max(3,v/mx*100):0}%;background:${i===0?"var(--warn)":"var(--accent)"}"></i></div>
        <div class="fcl">${i===0?"due":i}</div></div>`;}).join("")}
  </div>
  <p class="note">${fc[0]?`<b>${fc[0]}</b> waiting now.`:"Nothing overdue."} ${fc.slice(1).reduce((a,b)=>a+b,0)} more fall due within a fortnight, an average of ${(fc.slice(1).reduce((a,b)=>a+b,0)/14).toFixed(1)} a day.</p>

  <h2 class="sec">The labs</h2>
  <p class="sub">Seven workbenches. Each one hides the truth while you decide and reveals it afterwards, which is the only honest way to practise a judgement whose feedback is this noisy. Start any of them directly.</p>
  <div class="grid">${LABS.map(l=>{
    const k=S.sk["b:"+l.id];
    const acc=k&&k.seen?Math.round(k.ok/k.seen*100):null;
    return `<div class="mx click" data-lab="b:${esc(l.id)}">
      <div class="n"><span>${esc(l.name)}</span><em>${k&&k.seen?k.seen+" run"+(k.seen>1?"s":""):"not run"}</em></div>
      <div class="s">${esc(l.blurb)}</div>
      <div class="t"><i class="${acc===null?"":acc<50?"low":acc<80?"mid":""}" style="width:${acc===null?0:acc}%"></i></div></div>`;}).join("")}</div>

  <h2 class="sec">Weakest items</h2>
  <p class="sub">These come up first in every session until they stop being weak. A <b>leech</b> — six lapses or more — is usually a badly-understood concept rather than a badly-remembered fact: read the referenced section rather than drilling it again.</p>
  <div class="tblwrap"><table class="st"><thead><tr><th>Item</th><th>Domain</th><th class="r">Seen</th><th class="r">Right</th><th class="r">Lapses</th><th class="r">Stability</th><th></th></tr></thead><tbody>
  ${POOL.map(p=>({p,k:S.sk[p.key]})).filter(x=>x.k&&x.k.seen>=2&&!x.k.susp)
      .sort((a,b)=>(a.k.ok/a.k.seen)-(b.k.ok/b.k.seen)||b.k.lapses-a.k.lapses).slice(0,16)
      .map(x=>`<tr class="${isLeech(x.k)?"warn":""}"><td>${esc(x.p.name)}${isLeech(x.k)?' <span class="badge bad">leech</span>':""}</td>
        <td>${esc(x.p.dom)}</td><td class="r">${x.k.seen}</td><td class="r">${Math.round(x.k.ok/x.k.seen*100)}%</td>
        <td class="r">${x.k.lapses}</td><td class="r">${fmtDays(x.k.s)}</td>
        <td class="r"><button class="btn sm ghost" data-susp="${esc(x.p.key)}">suspend</button></td></tr>`).join("")
      || '<tr><td colspan="7" class="empty">Answer a few sets and the weak ones surface here.</td></tr>'}
  </tbody></table></div>

  ${susp.length?`<h2 class="sec">Suspended</h2>
  <p class="sub">${susp.length} item${susp.length>1?"s":""} withheld from the queue.</p>
  <div class="modes"><button class="btn" id="unsusp">Restore all ${susp.length}</button></div>`:""}

  <h2 class="sec">Your data</h2>
  <p class="sub">Everything is stored in this browser only. Nothing leaves the file, and nothing is sent anywhere. Export before switching machines — and note that clearing site data will erase it.</p>
  <div class="modes">
    <button class="btn" id="exp">Export progress</button>
    <button class="btn" id="imp">Import</button>
    <button class="btn" id="wipe">Reset everything</button>
  </div>`;

  $$("[data-lab]").forEach(el=>el.onclick=()=>startSingle(el.dataset.lab));
  $$("[data-kind]").forEach(el=>el.onclick=()=>{ hidePanel(); startKind(el.dataset.kind); });
  $$("[data-dom]").forEach(el=>el.onclick=()=>{
    MODE.dom=el.dataset.dom; const s=$("#dom"); if(s) s.value=el.dataset.dom;
    hidePanel(); start();
  });
  $$("[data-susp]").forEach(b=>b.onclick=()=>{ sk(b.dataset.susp).susp=1; saveNow(); renderStats(); });
  const un=$("#unsusp"); if(un) un.onclick=()=>{ Object.values(S.sk).forEach(k=>k.susp=0); saveNow(); renderStats(); updateBar(); };
  $("#exp").onclick=()=>{ const b=new Blob([JSON.stringify(S)],{type:"application/json"});
    const a=document.createElement("a"); a.href=URL.createObjectURL(b);
    a.download="trainer-progress-"+new Date().toISOString().slice(0,10)+".json"; a.click(); };
  $("#imp").onclick=()=>{ const f=document.createElement("input"); f.type="file"; f.accept=".json";
    f.onchange=()=>{ const r=new FileReader(); r.onload=()=>{ try{
      const p=JSON.parse(r.result); if(!p||typeof p!=="object") throw 0;
      S=Object.assign({}, S, p); S.settings=Object.assign({},DEF_SETTINGS,p.settings||{});
      saveNow(); renderStats(); updateBar();
    }catch(e){ alert("Could not read that file."); } }; r.readAsText(f.files[0]); }; f.click(); };
  $("#wipe").onclick=()=>{ window.__QC_ASK__("Erase all progress in this browser? This cannot be undone.").then(function(ok){
    if(!ok) return;
    S={v:2,created:Date.now(),n:0,streak:0,best:0,sk:{},ability:{},hist:[],journal:[],sessions:[],
       settings:Object.assign({},DEF_SETTINGS),daily:{},seenIntro:1};
    saveNow(); renderStats(); updateBar(); }); };
}

function renderJournal(){
  const j=S.journal;
  $("#panel").innerHTML=`<h2 class="sec">Mistake journal</h2>
  <p class="sub">Every item you got wrong, most recent first, with the exact numbers you saw and the working you needed. Re-reading a mistake three days later is worth more than three fresh questions — the retrieval failure is what marks the memory.</p>
  ${j.length? j.slice(0,60).map((m,i)=>`
    <div class="mx" style="margin-bottom:10px;padding:14px 16px">
      <div class="n"><span>${esc(m.name||m.dom)}</span><em>${esc(m.dom)} &middot; ${new Date(m.t).toLocaleDateString()}</em></div>
      <div style="font-family:var(--serif);font-size:16px;color:var(--ink);margin:8px 0 10px">${m.q}</div>
      <div style="font:600 13px var(--mono);color:var(--ink-3);margin-bottom:8px">
        you <span style="color:var(--neg)">${esc(m.yours)}</span> &middot; correct <b style="color:var(--ink)">${esc(m.correct)}</b> ${esc(m.unit||"")}</div>
      <div class="sol" style="border-top:1px solid var(--rule)">${m.sol}</div>
      <div class="selfrow"><button class="btn sm" data-retry="${esc(m.key)}">Try this item again</button></div>
    </div>`).join("")
   : '<p class="empty">Nothing here yet. Items you get wrong are recorded automatically, with the exact figures you were shown.</p>'}
  ${j.length?`<div class="modes"><button class="btn" id="clearj">Clear journal</button>
    <button class="btn on" id="drilljournal">Drill everything in the journal</button></div>`:""}`;
  $$("[data-retry]").forEach(b=>b.onclick=()=>{
    const p=BYKEY[b.dataset.retry]; if(!p) return;
    hidePanel(); clearInterval(drillT); queue=[p]; idx=0; relearn=[]; relearned=Object.create(null); sessionOk=0; sessionN=0; startedAt=Date.now(); render();
  });
  const cj=$("#clearj"); if(cj) cj.onclick=()=>{ S.journal=[]; saveNow(); renderJournal(); };
  const dj=$("#drilljournal"); if(dj) dj.onclick=()=>{
    const keys=[...new Set(S.journal.map(m=>m.key))].map(k=>BYKEY[k]).filter(Boolean);
    if(!keys.length) return;
    hidePanel(); clearInterval(drillT); queue=keys.slice(0,40); idx=0; relearn=[]; relearned=Object.create(null); sessionOk=0; sessionN=0; startedAt=Date.now(); render();
  };
}

function renderSettings(){
  const sw=(id,label,desc,on)=>`<div class="swrow"><div class="lab"><b>${label}</b><span>${desc}</span></div>
    <div class="sw ${on?"on":""}" data-sw="${id}" role="switch" aria-checked="${on}" tabindex="0"></div></div>`;
  $("#panel").innerHTML=`<h2 class="sec">Settings</h2>
  <p class="sub">Everything here is stored in this browser alongside your progress.</p>
  ${sw("conf","Ask for confidence","After you commit an answer and before you see the result. Scored by Brier — the meta-skill of knowing what you know.",S.settings.conf)}
  ${sw("timer","Show the clock","A target time per item, based on kind and difficulty. Informative, never punitive.",S.settings.timer)}
  ${sw("adaptive","Adaptive difficulty","Numeric problems get uglier numbers and more steps as a domain's accuracy rises.",S.settings.adaptive)}
  ${sw("autoAdv","Advance automatically on a correct answer","Moves on after a second and a half. Faster, at the cost of reading the working when you were right.",S.settings.autoAdv)}
  ${sw("commit","Write recall answers down before revealing","Self-grading is only honest if you committed to something first. One line is enough, and it is the difference between recognising an answer and producing one.",S.settings.commit)}
  ${sw("xref","Link every item to the reference","Turns the volume citation under each solution into a link. Requires the reference file to sit in the same folder.",S.settings.xref)}
  <div class="swrow"><div class="lab"><b>Reference file name</b>
    <span>The trainer links to this file, in the same folder, at the exact section for each item. ${Object.keys(XREF.sec||{}).length} sections are mapped.</span></div>
    <input class="btn" id="refname" style="width:220px;font-family:var(--mono);font-size:12.5px" value="${esc(S.settings.ref||"")}"></div>
  <div class="swrow"><div class="lab"><b>Daily goal</b>
    <span>Items a day. The run counter only advances on days you reach it — twenty a day for a year beats four hundred in a weekend, by a wide margin.</span></div>
    <input class="btn" id="goalnum" type="number" min="5" max="500" step="5" style="width:90px;font-family:var(--mono)" value="${S.settings.goal||20}"></div>

  <h2 class="sec">Keyboard</h2>
  <div class="kbdmap">
    <div><kbd>&crarr;</kbd> check, then next</div>
    <div><kbd>1</kbd>–<kbd>5</kbd> choose an option / rate confidence</div>
    <div><kbd>1</kbd>–<kbd>9</kbd> place a step, or flag a line</div>
    <div><kbd>space</kbd> reveal a recall card</div>
    <div><kbd>h</kbd> hint</div>
    <div><kbd>s</kbd> skip this item</div>
    <div><kbd>x</kbd> suspend this item</div>
    <div><kbd>u</kbd> undo a mis-keyed answer</div>
    <div><kbd>p</kbd> progress panel</div>
    <div><kbd>j</kbd> mistake journal</div>
    <div><kbd>b</kbd> browse the bank</div>
    <div><kbd>d</kbd> due items only</div>
    <div><kbd>t</kbd> theme</div>
    <div><kbd>esc</kbd> back to the queue</div>
    <div><kbd>?</kbd> this page</div>
  </div>

  <h2 class="sec">How the scheduling works</h2>
  <p class="sub" style="max-width:74ch">Each item carries a <b>stability</b> — the number of days until your chance of recalling it falls to about 90% — and a <b>difficulty</b>. Answering correctly multiplies stability; answering wrongly collapses it. Crucially, the increase is largest when you answer correctly <em>just before</em> you would have forgotten, which is why the queue deliberately makes you wait rather than showing you things while they are still fresh.</p>
  <p class="sub" style="max-width:74ch">Speed feeds into this too. A correct answer inside ${"⅓"} of the target time is graded <em>easy</em> and pushed further out; a correct answer at twice the target is graded <em>hard</em> and comes back sooner. Fluency and accuracy are tracked as separate things because they are separate things.</p>
  <p class="sub" style="max-width:74ch">Six lapses marks an item as a <b>leech</b>. That is a signal about comprehension rather than memory: go and read the referenced volume instead of drilling it a seventh time.</p>

  <h2 class="sec">The bank</h2>
  <div class="grid">
    ${["calc","judge","recall","derive","estimate","desk","formula","lab","sequence","spot","tune"].map(k=>{
      const n=POOL.filter(p=>p.kind===k).length;
      const seen=POOL.filter(p=>p.kind===k&&S.sk[p.key]&&S.sk[p.key].seen).length;
      return `<div class="mx"><div class="n"><span>${KINDNAME[k]}</span><em>${seen}/${n} seen</em></div>
        <div class="s">${KINDBLURB[k]}</div>
        <div class="t"><i style="width:${n?seen/n*100:0}%"></i></div></div>`;}).join("")}
  </div>`;
  $$("[data-sw]").forEach(el=>{
    const go=()=>{ const id=el.dataset.sw; S.settings[id]=!S.settings[id]; saveNow(); renderSettings(); };
    el.onclick=go;
    el.onkeydown=e=>{ if(e.key===" "||e.key==="Enter"){ e.preventDefault(); go(); } };
  });
  const rn=$("#refname"); if(rn) rn.onchange=()=>{ S.settings.ref=rn.value.trim(); saveNow(); };
  const gn=$("#goalnum"); if(gn) gn.onchange=()=>{
    const v=Math.max(5,Math.min(500,+gn.value||20)); S.settings.goal=v; gn.value=v; saveNow(); updateBar(); };
}


/* ============================================================
   12b. THE BANK — browse and jump to any single item.
   With several hundred items across eleven kinds, a queue is a
   poor way to find the one thing you want to practise. This is
   the index.
   ============================================================ */
let bankQ="", bankKind="";
function renderBank(){
  const kinds=[...new Set(POOL.map(p=>p.kind))]
    .sort((a,b)=>POOL.filter(p=>p.kind===b).length-POOL.filter(p=>p.kind===a).length);
  const q=bankQ.trim().toLowerCase();
  const rows=POOL.filter(p=>{
    if(bankKind && p.kind!==bankKind) return false;
    if(!q) return true;
    return (p.name+" "+p.dom+" "+p.key+" "+(KINDNAME[p.kind]||"")+" "+(p.vol||"")).toLowerCase().indexOf(q)>=0;
  }).sort((a,b)=> a.dom===b.dom ? (a.name<b.name?-1:1) : (a.dom<b.dom?-1:1));

  $("#panel").innerHTML=`<h2 class="sec">The bank</h2>
  <p class="sub">Every item in the trainer, ${POOL.length} of them. Click one to practise it on its own &mdash;
  useful when you know exactly what you are weak at, or when you want to work through one kind deliberately
  rather than waiting for the queue to offer it.</p>
  <div class="bkkinds">
    <button class="bkk${bankKind?"":" on"}" data-k="">All<em>${POOL.length}</em></button>
    ${kinds.map(k=>`<button class="bkk${bankKind===k?" on":""}" data-k="${k}">${KINDNAME[k]||k}<em>${POOL.filter(p=>p.kind===k).length}</em></button>`).join("")}
  </div>
  <div class="bkbar">
    <input type="search" id="bkq" placeholder="Search by name, domain or volume&hellip;" value="${esc(bankQ)}" spellcheck="false">
    <span class="bkcount">${rows.length} shown</span>
  </div>
  ${bankKind?`<p class="sub" style="margin-top:-6px">${KINDBLURB[bankKind]||""}
    <button class="btn ghost sm" id="bkrun" style="margin-left:6px">Practise ${rows.length>25?25:rows.length} of these</button></p>`:""}
  <div class="bklist">
    ${rows.length? rows.map(p=>{
      const k=S.sk[p.key];
      const seen=k&&k.seen?k.seen:0;
      const acc=seen?Math.round(k.ok/seen*100):null;
      const cls = !seen ? "" : (acc>=80?"done":acc<50?"weak":"");
      return `<div class="bkrow ${cls}" data-key="${esc(p.key)}" tabindex="0" role="button">
        <span class="bk2">${KINDNAME[p.kind]||p.kind}</span>
        <span class="bn">${esc(p.name)}</span>
        <span class="bd">${esc(p.dom)}</span>
        <span class="bs">${seen?acc+"%":"new"}</span></div>`;}).join("")
      : `<div class="bkempty">Nothing matches &ldquo;${esc(bankQ)}&rdquo;.</div>`}
  </div>`;

  const inp=$("#bkq");
  if(inp){
    inp.oninput=()=>{ bankQ=inp.value; const at=inp.selectionStart; renderBank();
      const n2=$("#bkq"); if(n2){ n2.focus(); try{ n2.setSelectionRange(at,at); }catch(e){} } };
    if(bankQ) inp.focus();
  }
  $$(".bkk").forEach(b=>b.onclick=()=>{ bankKind=b.dataset.k; renderBank(); });
  const run=$("#bkrun");
  if(run) run.onclick=()=>{ hidePanel(); startKind(bankKind); };
  $$(".bkrow").forEach(el=>{
    const go=()=>{ hidePanel(); startSingle(el.dataset.key); };
    el.onclick=go;
    el.onkeydown=e=>{ if(e.key==="Enter"||e.key===" "){ e.preventDefault(); go(); } };
  });
}
/* A session of one kind only — the natural companion to the browser. */
function startKind(kind){
  MODE.exam=false; MODE.speed=0; MODE.dueOnly=false; MODE.weak=false;
  MODE.kinds=kind?[kind]:null;
  MODE.mix = kind ? (function(){ const m={}; m[kind]=1; return "__one"; })() : (S.settings.mix||"balanced");
  if(kind){ MIXES.__one={}; MIXES.__one[kind]=1; }
  MODE.len=Math.min(25, POOL.filter(p=>!kind||p.kind===kind).length);
  syncChips(); start();
}

/* ============================================================
   13. INTRO
   ============================================================ */
function intro(){
  hidePanel();
  $("#prog").style.width="0%";
  const nMental=POOL.filter(p=>p.mental).length;
  $("#stage").innerHTML=`<div class="card-wrap fadein">
    <h2 class="sec" style="margin-top:0">Practice, not reading</h2>
    <p class="intro">Every number below is generated fresh, so nothing can be memorised — only worked out.
    Eleven kinds of item are shuffled together on purpose, because mixing them is what forces you to
    recognise <em>which</em> method applies, and that recognition is the skill being trained.</p>
    <p class="intro">Six of them ask you to produce rather than to pick, and they are where most of the
    learning happens. <b>Formula</b> items give you symbols and want the rule, tested against two hundred
    random inputs — so knowing one worked example is not enough. <b>Order it</b> gives you the steps of a real
    procedure and asks you to sequence them, because most professional failure is doing a known step at the
    wrong moment. <b>Spot the flaw</b> hands you a backtest, a risk report or a pitch with something wrong in
    it. <b>Tune it</b> gives you the controls of a trade-off and asks you to find the optimum, so you feel the
    shape of the curve rather than reading about it. <b>Derive</b> marks a multi-step chain one step at a time.
    And <b>Labs</b> hand you a running simulation: quote a market, work an order, hedge a gamma book, overfit a
    model on purpose, take a fund past its capacity. You decide, the world responds, and the truth is revealed
    only afterwards — because separating a good decision from a good outcome is the skill this trade is
    actually built on.</p>
    <div class="grid">
      <div class="mx"><div class="n"><span>Compute</span><em>${GENS.length} generators</em></div>
        <div class="s">Size a position, price an option, deflate a Sharpe, walk an order book. Marked to a tolerance, with the working either way. The answer box does arithmetic: type <code style="font-family:var(--mono)">2500/12.5</code>.</div></div>
      <div class="mx"><div class="n"><span>Judge</span><em>${JUDGE.length} scenarios</em></div>
        <div class="s">A broker, a backtest, a drawdown, a retry that doubled your position. One defensible answer each, and distractors people actually believe.</div></div>
      <div class="mx"><div class="n"><span>Recall</span><em>${CARDS.length} cards</em></div>
        <div class="s">The only self-graded part, because producing a definition cannot be auto-marked. Grade honestly.</div></div>
      <div class="mx"><div class="n"><span>Derive</span><em>${DERIVE.length} chains</em></div>
        <div class="s">Multi-step problems marked step by step. Is this strategy viable; price it and hedge it; should you believe this backtest.</div></div>
      <div class="mx"><div class="n"><span>Estimate</span><em>${ESTIM.length} Fermi problems</em></div>
        <div class="s">Order-of-magnitude reasoning under no information, graded on log error. Within a factor of two is the target.</div></div>
      <div class="mx"><div class="n"><span>Desk</span><em>${DESK.length} simulations</em></div>
        <div class="s">A situation unfolds over several rounds and your choices carry forward. No arithmetic to hide behind.</div></div>
      <div class="mx"><div class="n"><span>Formula</span><em>${FORMULA.length} rules</em></div>
        <div class="s">Symbols in, an expression out, checked against 200 random inputs. The difference between having done a calculation and knowing the rule.</div></div>
      <div class="mx"><div class="n"><span>Order it</span><em>${SEQ.length} procedures</em></div>
        <div class="s">A real procedure, its steps shuffled. Research an idea, validate a model without leaking, take a system to production, respond to an incident. The order <em>is</em> the knowledge, and partial credit is given for getting the relative order right.</div></div>
      <div class="mx"><div class="n"><span>Spot the flaw</span><em>${SPOT.length} listings</em></div>
        <div class="s">A backtest loop, a risk report, a research protocol, a pitch. One to three things are wrong. The bugs are the ones that actually occur — and they make results <em>better</em>, which is why they survive review.</div></div>
      <div class="mx"><div class="n"><span>Tune it</span><em>${TUNE.length} trade-offs</em></div>
        <div class="s">Move the controls until the objective is met, with the numbers updating live. Leverage, participation rate, stop distance, shrinkage, hedge frequency. Every one has an interior optimum, and the flatness near the top is half the lesson.</div></div>
      <div class="mx"><div class="n"><span>Lab</span><em>${LABS.length} workbenches</em></div>
        <div class="s">Real decisions against a simulated world, scored on the decision rather than the outcome. Start one directly:</div>
        <div class="labchips">${LABS.map(l=>`<button class="chip" data-lab="b:${esc(l.id)}" title="${esc(l.blurb)}">${esc(l.name)}</button>`).join("")}</div></div>
    </div>
    <p class="intro" style="font-size:16px">Items you get wrong return within a few questions and again tomorrow.
    Items you get right recede on a real calendar — days, then weeks, then months — so the queue fills, on its own,
    with whatever you are worst at, and empties of what you are not. That reordering is doing most of the work.</p>
    <p class="intro" style="font-size:16px">Two things make it faster than it looks. Every answer carries a <b>confidence</b>,
    scored so you can see whether you know what you know. And a <b>clock</b> runs against a target time, because a correct
    answer that took three minutes is not the same skill as the same answer in twenty seconds.</p>
    <div class="modes">
      <button class="btn on" id="go">Start&nbsp; <kbd>&crarr;</kbd></button>
      <button class="btn" id="goNum">Numbers only</button>
      <button class="btn" id="goDoing">Learn by doing</button>
      <button class="btn" id="goBank">Browse the bank</button>
      <button class="btn" id="goDrill">60-second speed drill</button>
      <button class="btn" id="goExam">Exam: 20 items, no help</button>
    </div>
    <p class="hint" style="margin-top:2px">A set of 25 takes eight to twelve minutes. Progress lives in this browser and can be exported. Press <kbd>?</kbd> at any time for the keyboard map.</p>
  </div>`;
  $("#go").onclick=()=>{ S.seenIntro=1; save(); start(); };
  $("#goNum").onclick=()=>{ S.seenIntro=1; save(); MODE.mix="numbers"; syncChips(); start(); };
  $$("[data-lab]").forEach(b=>b.onclick=()=>{ S.seenIntro=1; save(); startSingle(b.dataset.lab); });
  $("#goDoing").onclick=()=>{ S.seenIntro=1; save(); MODE.mix="doing"; MODE.len=6; MODE.budgetMs=0;
    S.settings.mix="doing"; syncChips(); start(); };
  $("#goBank").onclick=()=>{ S.seenIntro=1; save(); showPanel("bank"); };
  $("#goDrill").onclick=()=>{ S.seenIntro=1; save(); speedDrill(60); };
  $("#goExam").onclick=()=>{ S.seenIntro=1; save();
    MODE.exam=true; MODE.prevMix=MODE.mix; MODE.mix="exam"; MODE.len=20; syncChips(); start(); };
}

/* ============================================================
   14. SPEED DRILL
   ============================================================ */
let drillT=0, drillEnd=0, drillN=0, drillOk=0;
function speedDrill(secs){
  hidePanel();
  MODE.speed=1; MODE.mix="drill"; MODE.len=400; MODE.dueOnly=false; MODE.dom=null; MODE.kinds=["calc"];
  queue=buildQueue(); idx=0; relearn=[]; relearned=Object.create(null); sessionOk=0; sessionN=0; startedAt=Date.now();
  drillN=0; drillOk=0; drillEnd=Date.now()+secs*1000;
  if(!queue.length){ MODE.speed=0; start(); return; }
  clearInterval(drillT);
  drillT=setInterval(()=>{
    const left=drillEnd-Date.now();
    const el=$("#drillclock");
    if(el) el.innerHTML="<b>"+Math.max(0,left/1000).toFixed(1)+"s</b> left";
    if(left<=0){ clearInterval(drillT); drillDone(); }
  },100);
  render();
  showDrillBar(secs);
}
function showDrillBar(secs){
  const cnt=$("#cnt");
  if(cnt) cnt.outerHTML=`<span class="pill due-hot" id="drillclock"><b>${secs.toFixed(1)}s</b> left</span>`;
}
function drillDone(){
  MODE.speed=0; stopClock(); phase="done";
  const mins=(Date.now()-startedAt)/60000;
  $("#stage").innerHTML=`<div class="card-wrap fadein"><div class="done">
    <h2>${sessionOk} of ${sessionN} in the drill</h2>
    <div class="big" style="justify-content:center">
      <div><b>${sessionN?Math.round(sessionOk/sessionN*100):0}%</b><span>accuracy</span></div>
      <div><b>${(sessionN/Math.max(mins,0.01)).toFixed(1)}</b><span>per minute</span></div>
      <div><b>${sessionN?fmtDur((Date.now()-startedAt)/sessionN):"—"}</b><span>each</span></div>
    </div>
    <p class="intro" style="margin:18px auto 0;text-align:left">The drill only serves unit-conversion and mental-arithmetic items, because those are the ones that make everything else faster. A basis-point conversion that takes you eight seconds is eight seconds added to every cost calculation you will ever do.</p>
    <div class="modes" style="justify-content:center">
      <button class="btn on" id="again60">Again, 60s</button>
      <button class="btn" id="again180">Three minutes</button>
      <button class="btn" id="backNormal">Back to the mixed queue</button></div>
  </div></div>`;
  $("#prog").style.width="100%";
  $("#again60").onclick=()=>speedDrill(60);
  $("#again180").onclick=()=>speedDrill(180);
  $("#backNormal").onclick=()=>{ MODE.mix=S.settings.mix||"balanced"; MODE.kinds=null; restoreCnt(); syncChips(); start(); };
  updateBar();
}
function restoreCnt(){
  const d=$("#drillclock");
  if(d) d.outerHTML=`<span class="pill hideS" id="cnt">&mdash;</span>`;
}

/* ============================================================
   15. KEYBOARD
   ============================================================ */
document.addEventListener("keydown", e=>{
  if(e.metaKey||e.ctrlKey||e.altKey) return;
  const t=e.target, inInput = t && (t.tagName==="INPUT"||t.tagName==="TEXTAREA"||t.tagName==="SELECT");

  if(e.key==="Escape"){ if(panel){ e.preventDefault(); hidePanel(); if(!queue.length) start(); else render(); } return; }
  if(e.key==="?"){ e.preventDefault(); showPanel("settings"); return; }

  if(e.key==="Enter"){
    if(phase==="feedback" && $("#next")){ e.preventDefault(); advance(); return; }
    if(phase==="lab" && labKeyFn){ e.preventDefault(); labKeyFn(0); return; }
    if(phase==="answer" && $("#seqwrap")){ e.preventDefault();
      if(cur&&cur.placed&&cur.o&&cur.placed.length===cur.o.steps.length) submitSeq(); return; }
    if(phase==="answer" && $("#check")){ e.preventDefault();
      const k=cur&&cur.p&&cur.p.kind;
      if(k==="formula") submitFormula();
      else if(k==="spot") submitSpot();
      else if(k==="tune") submitTune();
      else if($("#steps")) submitStep(); else submitNum(); return; }
    if(phase==="conf"){ e.preventDefault(); pickConf(2); return; }
    if(phase==="selfgrade" && $("#g3")){ e.preventDefault(); gradeCard(3); return; }
    if($("#restart")){ e.preventDefault(); $("#restart").click(); return; }
    if($("#go")){ e.preventDefault(); $("#go").click(); return; }
    if($("#again60")){ e.preventDefault(); $("#again60").click(); return; }
    return;
  }
  if(inInput) return;

  if(phase==="lab" && labKeyFn && /^[1-9]$/.test(e.key)){ e.preventDefault(); labKeyFn(+e.key); return; }
  if(e.key===" " && phase==="answer" && $("#reveal")){ e.preventDefault(); revealCard(); return; }
  if(/^[1-5]$/.test(e.key)){
    const n=+e.key;
    if(phase==="conf"){ e.preventDefault(); pickConf(n-1); return; }
    if(phase==="selfgrade" && n<=4){ e.preventDefault(); gradeCard(n); return; }
    if(phase==="answer" && $("#opts")){ const b=$$("#opts .opt")[n-1]; if(b){ e.preventDefault(); b.click(); } return; }
    if(phase==="answer" && $("#dopts")){ const b=$$("#dopts .dopt")[n-1]; if(b){ e.preventDefault(); b.click(); } return; }
  }
  if(/^[1-9]$/.test(e.key) && phase==="answer"){
    const n=+e.key;
    if($("#seqwrap")){ const b=$$("#seqwrap .seqopt")[n-1]; if(b){ e.preventDefault(); b.click(); } return; }
    if($("#spotwrap")){ const b=$$("#spotwrap .spotline")[n-1]; if(b){ e.preventDefault(); b.click(); } return; }
  }
  if(e.key==="h" && phase==="answer"){ e.preventDefault(); const b=$("#hintb"); if(b) b.click(); return; }
  if(e.key==="s" && phase==="lab"){ e.preventDefault(); advance(); return; }
  if(e.key==="s" && (phase==="answer"||phase==="feedback")){ e.preventDefault(); advance(); return; }
  if(e.key==="u" && phase==="feedback"){ e.preventDefault(); if(undoLast()) render(); return; }
  if(e.key==="x"){ e.preventDefault();
    if(cur&&cur.p){ sk(cur.p.key).susp=1; saveNow(); advance(); } return; }
  if(e.key==="p"){ e.preventDefault(); panel==="stats"?hidePanel():showPanel("stats"); return; }
  if(e.key==="j"){ e.preventDefault(); panel==="journal"?hidePanel():showPanel("journal"); return; }
  if(e.key==="b"){ e.preventDefault(); panel==="bank"?hidePanel():showPanel("bank"); return; }
  if(e.key==="d"){ e.preventDefault(); const b=$("#dueBtn"); if(b) b.click(); return; }
  if(e.key==="t"){ e.preventDefault(); toggleTheme(); return; }
});

/* ============================================================
   16. CHROME WIRING
   ============================================================ */
function toggleTheme(){
  const r=document.documentElement, c=r.getAttribute("data-theme");
  const sys=window.matchMedia&&window.matchMedia("(prefers-color-scheme: dark)").matches;
  const n=c?(c==="dark"?"light":"dark"):(sys?"light":"dark");
  r.setAttribute("data-theme",n);
  try{ localStorage.setItem("trainer.theme",n); }catch(e){}
}
function syncChips(){
  /* The selected state has to reach assistive technology as well as the eye,
     so every toggle carries aria-pressed alongside its class. */
  const set=(b,on)=>{ if(!b) return; b.classList.toggle("on", on); b.setAttribute("aria-pressed", on?"true":"false"); };
  $$("[data-mix]").forEach(b=>set(b, !MODE.exam && !MODE.speed && b.dataset.mix===MODE.mix));
  $$("[data-len]").forEach(b=>set(b, !MODE.budgetMs && +b.dataset.len===MODE.len));
  $$("[data-mins]").forEach(b=>set(b, MODE.budgetMs===+b.dataset.mins*60000));
  set($("#dueBtn"), !!MODE.dueOnly);
  set($("#weakBtn"), !!MODE.weak);
  set($("#examBtn"), !!MODE.exam);
}
function boot(){
  load();
  try{ const t=localStorage.getItem("trainer.theme"); if(t) document.documentElement.setAttribute("data-theme",t); }catch(e){}
  MODE.mix=S.settings.mix||"balanced";
  updateBar();

  const sel=$("#dom");
  DOMAINS.forEach(d=>{ const o=document.createElement("option"); o.value=d;
    o.textContent=d+" ("+POOL.filter(p=>p.dom===d).length+")"; sel.appendChild(o); });
  sel.onchange=()=>{ MODE.dom=sel.value||null; S.seenIntro=1; save(); start(); };

  $$("[data-mix]").forEach(b=>b.onclick=()=>{ MODE.mix=b.dataset.mix; MODE.kinds=null; MODE.speed=0; MODE.exam=false;
    if(MODE.mix==="doing" && MODE.len>10){ MODE.len=6; MODE.budgetMs=0; }
    if(MODE.mix!=="doing" && MODE.len<10){ MODE.len=25; }
    S.settings.mix=MODE.mix; S.seenIntro=1; MODE.kinds=null; restoreCnt(); save(); syncChips(); start(); });
  $$("[data-len]").forEach(b=>b.onclick=()=>{ MODE.len=+b.dataset.len; MODE.budgetMs=0; MODE.speed=0; MODE.exam=false;
    S.seenIntro=1; restoreCnt(); save(); syncChips(); start(); });
  $$("[data-mins]").forEach(b=>b.onclick=()=>{ MODE.budgetMs=+b.dataset.mins*60000; MODE.len=400; MODE.speed=0; MODE.exam=false;
    S.seenIntro=1; restoreCnt(); save(); syncChips(); start(); });
  $("#dueBtn").onclick=()=>{ MODE.dueOnly=!MODE.dueOnly; MODE.speed=0; MODE.weak=false; MODE.exam=false;
    S.seenIntro=1; restoreCnt(); save(); syncChips(); start(); };
  $("#weakBtn").onclick=()=>{ MODE.weak=!MODE.weak; MODE.speed=0; MODE.dueOnly=false; MODE.exam=false;
    S.seenIntro=1; restoreCnt(); save(); syncChips(); start(); };
  $("#drillBtn").onclick=()=>{ S.seenIntro=1; save(); MODE.exam=false; speedDrill(60); };
  $("#examBtn").onclick=()=>{
    MODE.exam=!MODE.exam; MODE.speed=0; MODE.dueOnly=false; MODE.weak=false;
    if(MODE.exam){ MODE.prevMix=MODE.mix; MODE.mix="exam"; MODE.len=20; MODE.budgetMs=0; }
    else { MODE.mix=MODE.prevMix||S.settings.mix||"balanced"; MODE.len=25; }
    S.seenIntro=1; restoreCnt(); save(); syncChips(); start();
  };
  $$("[data-panel]").forEach(b=>b.onclick=()=>{
    if(panel===b.dataset.panel){ hidePanel(); if(queue.length) render(); else start(); }
    else showPanel(b.dataset.panel); });
  $("#theme").onclick=toggleTheme;
  $("#logo").onclick=()=>{ hidePanel(); intro(); };
  window.addEventListener("beforeunload", saveNow);
  document.addEventListener("visibilitychange", ()=>{ if(document.hidden) saveNow(); });

  syncChips();
  if(S.seenIntro) start(); else intro();
}
window.__TRAINER__={
  run:function(vols,len,cb){ MODE.exam=false; MODE.speed=0; MODE.dueOnly=false;
    MODE.weak=false; MODE.dom=null; MODE.kinds=null; MODE.mix=(S.settings.mix||"balanced");
    start({vols:vols, len:len, onDone:cb}); },
  count:function(vols){ return POOL.filter(function(p){ return vols.indexOf(String(p.vol))>=0; }).length; },
  due:function(){ return dueCount(); }
};

if(document.readyState==="loading") document.addEventListener("DOMContentLoaded", boot);
else boot();
})();
;
/* ownership handed back: block 77 ran before this file loaded */
try { window.__qcOwner(null); } catch (e) {}
